export default "<!DOCTYPE html>\r\n<html lang=\"en\" dir=\"ltr\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n<title>Site Finishing Tracker</title>\r\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n<link href=\"https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\">\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js\"></script>\r\n<style>\r\n  :root{\r\n    --bg: #eae6dc;\r\n    --panel: #f6f3ea;\r\n    --ink: #211d18;\r\n    --ink-soft: #6b6357;\r\n    --line: #cfc6b2;\r\n    --accent: #d9541c;\r\n    --amber: #e2a100;\r\n    --green: #4c7a3d;\r\n    --stone: #9a9080;\r\n    --danger: #b23a2e;\r\n    --radius: 3px;\r\n  }\r\n  *{ box-sizing:border-box; }\r\n  html,body{ margin:0; padding:0; }\r\n  body{\r\n    background:var(--bg); color:var(--ink);\r\n    font-family:'Archivo', Arial, sans-serif; font-size:15px; line-height:1.6;\r\n    -webkit-tap-highlight-color: transparent;\r\n  }\r\n  ::selection{ background: var(--accent); color:#fff; }\r\n  button{ font-family:inherit; }\r\n\r\n  /* ---- Header ---- */\r\n  header.top{\r\n    background: var(--ink); color:#f2ede0; padding: 16px 16px 14px;\r\n    position: sticky; top:0; z-index:20; border-bottom: 4px solid var(--accent);\r\n  }\r\n  .top-row{ display:flex; align-items:center; justify-content:space-between; gap:10px; }\r\n  .top-left{ display:flex; align-items:center; gap:10px; min-width:0; }\r\n  .back-btn{\r\n    border:1px solid #4a453a; background:transparent; color:#f2ede0; border-radius:var(--radius);\r\n    padding:7px 10px; font-size:13px; cursor:pointer; flex:0 0 auto;\r\n  }\r\n  header.top h1{ font-size:17px; font-weight:800; margin:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\r\n  header.top .sub{ font-size:12px; color:#c9c0ac; margin:2px 0 0; }\r\n  .progress-wrap{ min-width:100px; text-align:right; flex:0 0 auto; }\r\n  .progress-num{ font-size:20px; font-weight:900; color:#fff; line-height:1; }\r\n  .progress-label{ font-size:10.5px; color:#c9c0ac; margin-top:2px;}\r\n  .bar-track{ margin-top:10px; height:7px; background:#3a352c; border-radius:99px; overflow:hidden; }\r\n  .bar-fill{ height:100%; background: var(--accent); width:0%; transition: width .35s ease; }\r\n\r\n  .toolbar{\r\n    display:flex; gap:6px; margin-top:10px; flex-wrap:wrap;\r\n  }\r\n  .tool-btn{\r\n    border:1px solid #4a453a; background:#2b271f; color:#f2ede0; font-size:12px; font-weight:600;\r\n    padding:7px 11px; border-radius:var(--radius); cursor:pointer;\r\n  }\r\n  .tool-btn:hover{ border-color: var(--accent); }\r\n\r\n  /* ---- Filters ---- */\r\n  .filters{\r\n    position:sticky; top:0; z-index:19; background: var(--bg);\r\n    display:flex; flex-direction:column; gap:8px; padding:10px 16px; border-bottom:1px solid var(--line);\r\n  }\r\n  .search-row{ position:relative; }\r\n  .search-input{\r\n    width:100%; border:1px solid var(--line); border-radius:var(--radius); padding:8px 32px 8px 12px;\r\n    font-family:inherit; font-size:13.5px; background:var(--panel); color:var(--ink); box-sizing:border-box;\r\n  }\r\n  .search-input:focus{ outline:none; border-color:var(--accent); }\r\n  .search-clear{\r\n    position:absolute; inset-inline-end:6px; top:50%; transform:translateY(-50%);\r\n    border:none; background:none; color:var(--ink-soft); font-size:16px; line-height:1; cursor:pointer; padding:4px; display:none;\r\n  }\r\n  .chip-row{ display:flex; gap:6px; overflow-x:auto; }\r\n  .chip-row::-webkit-scrollbar{ display:none; }\r\n  .chip{\r\n    flex:0 0 auto; padding:7px 14px; border:1px solid var(--line); background:var(--panel);\r\n    color:var(--ink-soft); font-size:12.5px; font-weight:600; border-radius:99px; cursor:pointer; white-space:nowrap;\r\n  }\r\n  .chip.active{ background: var(--ink); border-color:var(--ink); color:#fff; }\r\n\r\n  main{ padding: 14px 14px 100px; max-width:760px; margin:0 auto; }\r\n\r\n  /* ---- Home / space list ---- */\r\n  .home-sort{\r\n    position:sticky; top:0; z-index:19; background: var(--bg);\r\n    display:flex; align-items:center; gap:10px; padding:10px 16px; border-bottom:1px solid var(--line); flex-wrap:wrap;\r\n  }\r\n  .home-sort-label{ font-size:12px; color:var(--ink-soft); font-weight:600; flex:0 0 auto; }\r\n  .home-sort-hint{ font-size:11.5px; color:var(--ink-soft); font-style:italic; flex:0 0 auto; }\r\n  .space-card{\r\n    background:var(--panel); border:1px solid var(--line); border-inline-start:5px solid var(--accent);\r\n    border-radius:var(--radius); padding:14px 16px; margin-bottom:10px; cursor:pointer;\r\n    display:flex; align-items:center; gap:10px;\r\n  }\r\n  .space-card.dragging{ opacity:0.85; box-shadow:0 6px 16px rgba(0,0,0,0.18); }\r\n  .space-card .drag-handle{\r\n    flex:0 0 auto; color:var(--ink-soft); font-size:20px; line-height:1; letter-spacing:-2px;\r\n    padding:10px 6px; margin:-10px -6px; cursor:grab; touch-action:none; user-select:none;\r\n  }\r\n  .space-card .drag-handle:active{ cursor:grabbing; }\r\n  .space-card.selected{ background:#fbe9e0; border-inline-start-color:var(--danger); }\r\n  .select-circle{\r\n    flex:0 0 auto; width:22px; height:22px; border-radius:50%; border:2px solid var(--line);\r\n    display:flex; align-items:center; justify-content:center; font-size:13px; font-weight:900; color:#fff; background:#fff;\r\n  }\r\n  .select-circle.checked{ background:var(--danger); border-color:var(--danger); }\r\n  .space-card .space-card-body{ flex:1; min-width:0; }\r\n  .space-card h3{ margin:0 0 4px; font-size:16px; }\r\n  .space-card .meta{ font-size:12px; color:var(--ink-soft); display:flex; justify-content:space-between; gap:10px; }\r\n  .space-card .mini-bar{ height:5px; background:var(--line); border-radius:99px; margin-top:8px; overflow:hidden;}\r\n  .space-card .mini-fill{ height:100%; background:var(--green); }\r\n\r\n  .cat-heading{\r\n    font-size:13px; font-weight:700; color:var(--ink-soft); margin: 22px 4px 8px; padding-bottom:6px;\r\n    border-bottom:2px solid var(--line); display:flex; justify-content:space-between; align-items:center;\r\n  }\r\n  .cat-heading:first-child{ margin-top:4px; }\r\n  .cat-count{ font-weight:500; color:var(--stone); }\r\n\r\n  .card{\r\n    background:var(--panel); border:1px solid var(--line); border-inline-start: 5px solid var(--stone);\r\n    border-radius: var(--radius); padding: 12px 14px; margin-bottom:10px;\r\n  }\r\n  .card.status-inprogress{ border-inline-start-color: var(--amber); }\r\n  .card.status-done{ border-inline-start-color: var(--green); }\r\n\r\n  .card-head{ display:flex; justify-content:space-between; align-items:flex-start; gap:8px; }\r\n  .task-title{\r\n    font-weight:700; font-size:15px; flex:1; background:transparent; border:none; color:var(--ink);\r\n    font-family:inherit; resize:none; width:100%; padding:0; outline:none;\r\n  }\r\n  .del-btn{ border:none; background:transparent; color:var(--stone); font-size:16px; cursor:pointer; padding:2px 4px; line-height:1; }\r\n  .del-btn:hover{ color:var(--danger); }\r\n\r\n  .field-label{ font-size:11px; color:var(--ink-soft); margin: 8px 0 3px; display:block; }\r\n  .prereq-input, .notes-input, .cat-select{\r\n    width:100%; border:1px solid var(--line); background:#fff; border-radius:var(--radius);\r\n    padding:7px 9px; font-family:inherit; font-size:13px; color:var(--ink); outline:none;\r\n  }\r\n  .prereq-input, .cat-select{ resize:none; }\r\n  .notes-input{ resize:vertical; min-height:44px; }\r\n  .prereq-input:focus, .notes-input:focus, .task-title:focus, .cat-select:focus{ border-color: var(--accent); }\r\n\r\n  .dep-chips{ display:flex; flex-wrap:wrap; gap:6px; align-items:center; }\r\n  .dep-chip{\r\n    display:inline-flex; align-items:center; gap:6px; background:#fff; border:1px solid var(--line); border-radius:99px;\r\n    padding:5px 6px 5px 11px; font-size:12px; color:var(--ink);\r\n  }\r\n  .dep-chip .dep-remove{ border:none; background:var(--line); color:var(--ink); border-radius:50%; width:16px; height:16px; font-size:11px; line-height:1; cursor:pointer; padding:0; }\r\n  .dep-add-btn{\r\n    border:1px dashed var(--line); background:#fff; color:var(--ink-soft); font-size:12px; padding:6px 11px;\r\n    border-radius:99px; cursor:pointer;\r\n  }\r\n  .dep-add-btn:hover{ border-color:var(--accent); color:var(--accent); }\r\n  .dep-picker-modal{ max-width:420px; }\r\n  .dep-picker-list{ max-height:320px; overflow-y:auto; margin:12px 0; border:1px solid var(--line); border-radius:var(--radius); }\r\n  .dep-picker-item{ display:flex; align-items:center; gap:9px; padding:9px 10px; border-bottom:1px solid #eee; font-size:13.5px; cursor:pointer; }\r\n  .dep-picker-item:last-child{ border-bottom:none; }\r\n  .dep-picker-cat{ font-size:11.5px; color:var(--ink-soft); }\r\n\r\n  .status-row{ display:flex; gap:8px; margin-top:10px; flex-wrap:wrap; }\r\n  .status-btn{\r\n    flex:1; min-width:90px; padding:8px 6px; text-align:center; font-size:12px; font-weight:700;\r\n    border:1px solid var(--line); background:#fff; color:var(--ink-soft); cursor:pointer; border-radius: var(--radius);\r\n  }\r\n  .status-btn[data-s=\"notstarted\"].sel{ background: var(--stone); color:#fff; border-color:var(--stone); }\r\n  .status-btn[data-s=\"inprogress\"].sel{ background: var(--amber); color:#231c04; border-color:var(--amber); }\r\n  .status-btn[data-s=\"done\"].sel{ background: var(--green); color:#fff; border-color:var(--green); }\r\n\r\n  .date-row{ display:flex; gap:8px; margin-top:10px; }\r\n  .date-field{ flex:1; }\r\n  .date-field input{\r\n    width:100%; border:1px solid var(--line); background:#fff; border-radius:var(--radius);\r\n    padding:6px 8px; font-family:inherit; font-size:12.5px; color:var(--ink);\r\n  }\r\n\r\n  .photo-row{ margin-top:10px; display:flex; align-items:center; gap:10px; flex-wrap:wrap; }\r\n  .photo-thumb-wrap{ position:relative; display:inline-block; }\r\n  .photo-thumb{ width:64px; height:64px; object-fit:cover; border-radius:var(--radius); border:1px solid var(--line); cursor:pointer; display:block; }\r\n  .photo-remove-btn{\r\n    position:absolute; top:-7px; right:-7px; width:20px; height:20px; border-radius:50%;\r\n    background:var(--danger); color:#fff; border:2px solid var(--panel); font-size:13px; line-height:1;\r\n    cursor:pointer; display:flex; align-items:center; justify-content:center; padding:0;\r\n  }\r\n  .photo-remove-btn:hover{ opacity:0.85; }\r\n  .photo-btn{\r\n    display:inline-flex; align-items:center; gap:6px; border:1px dashed var(--line); background:#fff;\r\n    color:var(--ink-soft); font-size:12px; padding:8px 12px; border-radius:var(--radius); cursor:pointer;\r\n  }\r\n  .photo-btn:hover{ border-color: var(--accent); color:var(--accent); }\r\n  input[type=file]{ display:none; }\r\n\r\n  .add-bar{ position:fixed; bottom:0; right:0; left:0; padding:12px 16px; background:linear-gradient(to top, var(--bg) 60%, transparent); }\r\n  .add-btn{\r\n    max-width:760px; margin:0 auto; display:block; width:100%; background: var(--accent); color:#fff; border:none;\r\n    padding:13px; font-size:14.5px; font-weight:800; border-radius: var(--radius); cursor:pointer;\r\n  }\r\n  .add-btn:active{ opacity:0.85; }\r\n  .add-btn.secondary{ background:var(--ink); }\r\n  .add-btn.danger{ background:var(--danger); }\r\n  .add-btn:disabled{ opacity:0.4; cursor:default; }\r\n\r\n  .empty{ text-align:center; color:var(--ink-soft); padding:40px 20px; font-size:13.5px; }\r\n\r\n  .toast{\r\n    position:fixed; bottom:74px; left:50%; transform:translateX(-50%); background: var(--ink); color:#fff;\r\n    padding:9px 18px; border-radius:99px; font-size:12.5px; opacity:0; pointer-events:none; transition:opacity .25s ease; z-index:40;\r\n  }\r\n  .toast.show{ opacity:1; }\r\n\r\n  .lightbox{ position:fixed; inset:0; background:rgba(20,17,12,0.9); display:none; align-items:center; justify-content:center; z-index:50; padding:20px; }\r\n  .lightbox.open{ display:flex; }\r\n  .lightbox img{ max-width:100%; max-height:85vh; border-radius:4px; }\r\n  .lightbox .close{ position:absolute; top:16px; left:16px; color:#fff; font-size:26px; background:none; border:none; cursor:pointer;}\r\n\r\n  .modal-overlay{ position:fixed; inset:0; background:rgba(20,17,12,0.55); display:none; align-items:center; justify-content:center; z-index:60; padding:20px; }\r\n  .modal-overlay.open{ display:flex; }\r\n  .modal{ background:var(--panel); border-radius:6px; padding:20px; max-width:380px; width:100%; }\r\n  .modal h3{ margin:0 0 12px; font-size:16px; }\r\n  .modal input{ width:100%; border:1px solid var(--line); border-radius:var(--radius); padding:9px 10px; font-family:inherit; font-size:14px; }\r\n  .modal-actions{ display:flex; gap:8px; margin-top:14px; }\r\n  .modal-actions button{ flex:1; padding:10px; border-radius:var(--radius); border:none; font-weight:700; cursor:pointer; }\r\n  .modal-actions .confirm{ background:var(--accent); color:#fff; }\r\n  .modal-actions .cancel{ background:#e2ddd0; color:var(--ink); }\r\n\r\n  /* ---- Report view ---- */\r\n  #reportView, #historyView{ display:none; background:#fff; }\r\n  #reportView.open, #historyView.open{ display:block; position:fixed; inset:0; z-index:55; overflow:auto; }\r\n  .history-item{\r\n    display:flex; justify-content:space-between; align-items:center; gap:12px; flex-wrap:wrap;\r\n    padding:14px 0; border-bottom:1px solid #eee;\r\n  }\r\n  .history-date{ font-weight:700; font-size:14px; }\r\n  .history-meta{ font-size:12px; color:var(--ink-soft); margin-top:2px; }\r\n  .history-view-btn{\r\n    border:1px solid var(--line); background:var(--panel); padding:7px 14px; border-radius:var(--radius);\r\n    cursor:pointer; font-size:12.5px; font-weight:600;\r\n  }\r\n  .history-view-btn:hover{ border-color:var(--accent); color:var(--accent); }\r\n  .report-page{ max-width:760px; margin:0 auto; padding:30px 24px 80px; }\r\n  .report-header{ border-bottom:3px solid var(--ink); padding-bottom:14px; margin-bottom:18px; }\r\n  .report-header h1{ font-size:22px; margin:0 0 4px; }\r\n  .report-header .meta{ font-size:12.5px; color:var(--ink-soft); }\r\n  .report-summary{ display:flex; gap:18px; margin:14px 0 22px; font-size:13px; }\r\n  .report-cat{ font-size:14px; font-weight:800; margin:22px 0 10px; border-bottom:1px solid var(--line); padding-bottom:6px; }\r\n  .report-item{ margin-bottom:14px; padding-bottom:14px; border-bottom:1px solid #eee; }\r\n  .report-item .rt-title{ font-weight:700; font-size:14px; }\r\n  .report-badge{\r\n    display:inline-block; font-size:10.5px; font-weight:700; padding:2px 8px; border-radius:99px; margin-inline-start:8px;\r\n    color:#fff; vertical-align:middle;\r\n  }\r\n  .rb-notstarted{ background:var(--stone); } .rb-inprogress{ background:var(--amber); color:#231c04; } .rb-done{ background:var(--green); }\r\n  .report-item .rt-line{ font-size:12.5px; color:var(--ink-soft); margin-top:3px; }\r\n  .report-item img{ max-width:260px; max-height:200px; margin-top:8px; border-radius:4px; border:1px solid var(--line); display:block; }\r\n  .report-toolbar{\r\n    position:sticky; top:0; background:#fff; border-bottom:1px solid var(--line); padding:10px 16px;\r\n    display:flex; gap:8px; justify-content:center; z-index:5;\r\n  }\r\n  .report-toolbar button{ border:1px solid var(--line); background:var(--panel); padding:8px 14px; border-radius:var(--radius); cursor:pointer; font-size:13px; font-weight:600; }\r\n  .report-toolbar button.primary{ background:var(--accent); color:#fff; border-color:var(--accent); }\r\n  .report-status-section{ margin:26px 0; }\r\n  .report-status-heading{\r\n    font-size:15px; font-weight:800; margin:0 0 12px; padding-bottom:6px; border-bottom:2px solid var(--line);\r\n    display:inline-block; padding-inline-end:10px;\r\n  }\r\n  .report-status-heading.sh-done{ color:var(--green); border-color:var(--green); }\r\n  .report-status-heading.sh-inprogress{ color:#8a6400; border-color:var(--amber); }\r\n  .report-status-heading.sh-notstarted{ color:var(--ink-soft); border-color:var(--stone); }\r\n  .report-status-empty{ font-size:13px; color:var(--ink-soft); font-style:italic; }\r\n  .report-status-item{ font-size:13.5px; line-height:1.7; margin:0 0 14px; }\r\n  .report-status-item .rt-cat{ font-size:11.5px; color:var(--ink-soft); }\r\n  .report-status-item img{ max-width:260px; max-height:200px; margin-top:6px; border-radius:4px; border:1px solid var(--line); display:block; }\r\n  .gantt-legend{ display:flex; gap:16px; font-size:12px; color:var(--ink-soft); margin:10px 0 18px; flex-wrap:wrap; }\r\n  .gantt-swatch{ display:inline-block; width:12px; height:12px; border-radius:2px; margin-inline-end:5px; vertical-align:middle; }\r\n  .gantt-swatch.gantt-done{ background:var(--green); }\r\n  .gantt-swatch.gantt-inprogress{ background:var(--amber); }\r\n  .gantt-swatch.gantt-notstarted{ background:var(--stone); }\r\n  .gantt-wrap{ display:flex; border:1px solid var(--line); border-radius:4px; overflow:hidden; }\r\n  .gantt-labels{ flex:0 0 auto; border-inline-end:1px solid var(--line); background:var(--panel); }\r\n  .gantt-label-header{ height:28px; line-height:28px; font-size:11px; font-weight:700; color:var(--ink-soft); padding:0 10px; border-bottom:1px solid var(--line); background:#efe9d8; box-sizing:border-box; }\r\n  .gantt-label-row{\r\n    height:34px; line-height:34px; padding:0 10px; font-size:12.5px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;\r\n    border-bottom:1px solid #eee; box-sizing:border-box;\r\n  }\r\n  .gantt-scroll{ overflow-x:auto; flex:1 1 auto; }\r\n  .gantt-ticks{ position:relative; height:28px; border-bottom:1px solid var(--line); background:#efe9d8; box-sizing:border-box; }\r\n  .gantt-tick{ position:absolute; top:0; height:28px; line-height:28px; font-size:10.5px; color:var(--ink-soft); padding-inline-start:4px; border-inline-start:1px solid var(--line); white-space:nowrap; box-sizing:border-box; }\r\n  .gantt-rows{ position:relative; background-image:repeating-linear-gradient(to bottom, transparent 0, transparent 33px, #eee 33px, #eee 34px); }\r\n  .gantt-bar{\r\n    position:absolute; height:22px; border-radius:4px; display:flex; align-items:center; overflow:hidden;\r\n    padding:0 6px; box-sizing:border-box;\r\n  }\r\n  .gantt-bar-label{ font-size:11px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; color:#fff; }\r\n  .gantt-bar.gantt-done{ background:var(--green); }\r\n  .gantt-bar.gantt-inprogress{ background:var(--amber); }\r\n  .gantt-bar.gantt-inprogress .gantt-bar-label{ color:#231c04; }\r\n  .gantt-bar.gantt-notstarted{ background:var(--stone); }\r\n  @media print{\r\n    /* Print only #reportView: display:none (not visibility:hidden) removes\r\n       the rest of the app from the layout entirely, so the browser paginates\r\n       just the report content instead of reserving space for the whole\r\n       on-screen app and effectively \"screenshotting\" one giant page. */\r\n    body > *:not(#reportView){ display:none !important; }\r\n    #reportView{ position:static !important; }\r\n    .report-toolbar{ display:none !important; }\r\n    .report-page{ max-width:none !important; padding:0 !important; }\r\n    .report-item, .report-status-item{ break-inside:avoid; page-break-inside:avoid; }\r\n    .report-cat, .report-status-heading{ break-after:avoid; page-break-after:avoid; }\r\n  }\r\n.portal-nav{display:flex;align-items:center;gap:24px;padding:12px 20px;background:#142c30;color:#fff;font-size:12px}.portal-nav a{color:#fff;text-decoration:none}.portal-nav span{flex:1;font-weight:800;letter-spacing:2px}.space-card{border-radius:10px}button{cursor:pointer} </style>\r\n</head>\r\n<body><nav class=\"portal-nav\"><a href=\"/\">← Dashboard</a><span>FIELD WORKSPACE</span><a href=\"/#visits\">Visit log</a><a href=\"/#reports\">Weekly Project Reports</a><a href=\"/5s\">Site 5S & Appearance</a></nav>\r\n\r\n<header class=\"top\" id=\"mainHeader\">\r\n  <div class=\"top-row\">\r\n    <div class=\"top-left\">\r\n      <button class=\"back-btn\" id=\"backBtn\" style=\"display:none;\">&larr; Spaces</button>\r\n      <div>\r\n        <h1 id=\"headerTitle\">Site Finishing Tracker</h1>\r\n        <p class=\"sub\" id=\"headerSub\">Select or create a space to begin</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"progress-wrap\" id=\"progressWrap\" style=\"display:none;\">\r\n      <div class=\"progress-num\" id=\"progressNum\">0%</div>\r\n      <div class=\"progress-label\" id=\"progressLabel\">0 of 0 done</div>\r\n    </div>\r\n  </div>\r\n  <div class=\"bar-track\" id=\"barTrack\" style=\"display:none;\"><div class=\"bar-fill\" id=\"barFill\"></div></div>\r\n  <div class=\"toolbar\" id=\"spaceToolbar\" style=\"display:none;\">\r\n    <button class=\"tool-btn\" id=\"exportExcelBtn\">Export Excel</button>\r\n    <button class=\"tool-btn\" id=\"importExcelBtn\">Import Excel</button>\r\n    <input type=\"file\" id=\"importExcelInput\" accept=\".xlsx,.xls,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel\" style=\"display:none;\">\r\n    <button class=\"tool-btn\" id=\"reportBtn\">Generate report</button>\r\n    <button class=\"tool-btn\" id=\"statusReportBtn\">Detailed status report</button>\r\n    <button class=\"tool-btn\" id=\"timelineBtn\">Timeline (Gantt)</button>\r\n    <button class=\"tool-btn\" id=\"historyBtn\">Report history</button>\r\n    <button class=\"tool-btn\" id=\"reportDateBtn\">Report date</button>\r\n    <button class=\"tool-btn\" id=\"renameSpaceBtn\">Rename space</button>\r\n  </div>\r\n  <div class=\"toolbar\" id=\"homeToolbar\">\r\n    <button class=\"tool-btn\" id=\"backupBtn\">Backup all data (.json)</button>\r\n    <button class=\"tool-btn\" id=\"restoreBtn\">Restore backup</button>\r\n    <input type=\"file\" id=\"restoreInput\" accept=\".json,application/json,text/plain\" style=\"display:none;\">\r\n    <button class=\"tool-btn\" id=\"exportReportsBtn\">Export all reports (HTML)</button>\r\n    <button class=\"tool-btn\" id=\"editSpacesBtn\">Edit</button>\r\n    <button class=\"tool-btn\" id=\"selectAllBtn\" style=\"display:none;\">Select all</button>\r\n  </div>\r\n</header>\r\n\r\n<div class=\"home-sort\" id=\"homeSort\" style=\"display:none;\">\r\n  <span class=\"home-sort-label\">Sort:</span>\r\n  <div class=\"chip-row\">\r\n    <div class=\"chip active\" data-sort=\"manual\">Manual</div>\r\n    <div class=\"chip\" data-sort=\"name\">Name</div>\r\n    <div class=\"chip\" data-sort=\"reportDate\">Report date</div>\r\n  </div>\r\n  <span class=\"home-sort-hint\" id=\"homeSortHint\">Drag &#9776; to reorder</span>\r\n</div>\r\n\r\n<div class=\"filters\" id=\"filters\" style=\"display:none;\">\r\n  <div class=\"search-row\">\r\n    <input type=\"text\" class=\"search-input\" id=\"taskSearch\" placeholder=\"Search tasks...\">\r\n    <button class=\"search-clear\" id=\"searchClear\" title=\"Clear search\">&times;</button>\r\n  </div>\r\n  <div class=\"chip-row\">\r\n    <div class=\"chip active\" data-f=\"all\">All</div>\r\n    <div class=\"chip\" data-f=\"notstarted\">Not started</div>\r\n    <div class=\"chip\" data-f=\"inprogress\">In progress</div>\r\n    <div class=\"chip\" data-f=\"done\">Completed</div>\r\n  </div>\r\n</div>\r\n\r\n<main id=\"main\"></main>\r\n\r\n<div class=\"add-bar\" id=\"addBar\">\r\n  <button class=\"add-btn\" id=\"addBtn\">+ Add new space</button>\r\n  <button class=\"add-btn danger\" id=\"deleteSelectedBtn\" style=\"display:none;\" disabled>Delete</button>\r\n</div>\r\n\r\n<div class=\"toast\" id=\"toast\"></div>\r\n<div class=\"lightbox\" id=\"lightbox\">\r\n  <button class=\"close\" id=\"lbClose\">&times;</button>\r\n  <img id=\"lbImg\" src=\"\" alt=\"\">\r\n</div>\r\n\r\n<div class=\"modal-overlay\" id=\"modalOverlay\">\r\n  <div class=\"modal\">\r\n    <h3 id=\"modalTitle\">New space</h3>\r\n    <input type=\"text\" id=\"modalInput\" placeholder=\"e.g. Unit 3 - Kitchen\">\r\n    <div class=\"modal-actions\">\r\n      <button class=\"cancel\" id=\"modalCancel\">Cancel</button>\r\n      <button class=\"confirm\" id=\"modalConfirm\">Save</button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"modal-overlay\" id=\"depPickerOverlay\">\r\n  <div class=\"modal dep-picker-modal\">\r\n    <h3>Select dependencies</h3>\r\n    <div class=\"dep-picker-list\" id=\"depPickerList\"></div>\r\n    <div class=\"modal-actions\">\r\n      <button class=\"cancel\" id=\"depPickerCancel\">Cancel</button>\r\n      <button class=\"confirm\" id=\"depPickerConfirm\">Done</button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<div id=\"reportView\">\r\n  <div class=\"report-toolbar\">\r\n    <button id=\"reportBack\">&larr; Back to checklist</button>\r\n    <button id=\"reportDownload\">Download HTML</button>\r\n    <button class=\"primary\" id=\"reportPrint\">Print / Save as PDF</button>\r\n  </div>\r\n  <div class=\"report-page\" id=\"reportContent\"></div>\r\n</div>\r\n\r\n<div id=\"historyView\">\r\n  <div class=\"report-toolbar\">\r\n    <button id=\"historyBack\">&larr; Back to checklist</button>\r\n  </div>\r\n  <div class=\"report-page\" id=\"historyList\"></div>\r\n</div>\r\n\r\n<script>\r\n/* Online storage adapter */\nasync function dataRequest(store, options = {}, params = {}) {\n const query = new URLSearchParams({store,...params});\n const response = await fetch('/api/data?' + query, {headers:{'Content-Type':'application/json'},...options});\n const data = await response.json();\n if(!response.ok) throw new Error(data.error || 'Unable to access online storage');\n return data;\n}\nasync function openDB(){ await dataRequest('spaces'); }\nfunction dbGetAll(store){ return dataRequest(store); }\nfunction dbGetAllByIndex(store,index,key){ return dataRequest(store,{}, {[index]:key}); }\nfunction dbGet(store,key){ return dataRequest(store,{}, {id:key}); }\nfunction dbPut(store,val){ return dataRequest(store,{method:'PUT',body:JSON.stringify(val)}); }\nfunction dbDelete(store,key){ return dataRequest(store,{method:'DELETE'}, {id:key}); }\nwindow.addEventListener('unhandledrejection', e => { console.error(e.reason); showToast('Unable to save or load. Check your connection and retry.'); });\n/* ================= App state ================= */\r\nconst STATUS = { notstarted: 'Not started', inprogress: 'In progress', done: 'Completed' };\r\nlet currentSpace = null;   // {id, name, createdAt}\r\nlet tasks = [];\r\nlet photoCache = {};\r\nlet currentFilter = 'all';\r\nlet currentSearch = '';\r\nlet saveTimers = {};\r\nlet modalOnConfirm = null;\r\nlet depPickerTaskId = null;\r\nlet sortMode = localStorage.getItem('spaceSortMode') || 'manual';\r\nlet reportBackTarget = 'checklist';\r\nlet editMode = false;\r\nlet selectedSpaceIds = new Set();\r\n\r\nconst DEFAULT_TASKS = [\r\n[\"Surface Preparation\",\"Inspect plaster and fix defects (cracks, unevenness)\",\"Plastering fully complete and walls/ceiling dry\"],\r\n[\"Surface Preparation\",\"Final edge and joint touch-up on plastered walls\",\"Plaster defect inspection complete\"],\r\n[\"Tiling & Ceramics\",\"Kitchen wall tiling\",\"Rough plumbing (stub-outs) installed and wall prepped\"],\r\n[\"Tiling & Ceramics\",\"Bathroom and WC wall tiling\",\"Rough plumbing and waterproofing membrane on floor\"],\r\n[\"Tiling & Ceramics\",\"Floor tiling / ceramics in rooms and corridors\",\"Floor leveling and concrete screed complete\"],\r\n[\"Tiling & Ceramics\",\"Tile grouting (kitchen, bathrooms, floors)\",\"Tile adhesive fully cured (24-48h after tiling)\"],\r\n[\"Tiling & Ceramics\",\"Silicone sealing at wet-area joints (tub, sink, countertop)\",\"Grouting complete and fully cured\"],\r\n[\"Stone Work\",\"Staircase and landing stone work\",\"Structural work and stair concrete complete\"],\r\n[\"Stone Work\",\"Door and window sill / threshold stone\",\"Door and window frames installed\"],\r\n[\"Flooring\",\"Parquet / laminate flooring installation\",\"Floor fully dry and wall painting complete\"],\r\n[\"Flooring\",\"Skirting / baseboard installation\",\"Flooring and wall painting complete\"],\r\n[\"Drywall & False Ceiling\",\"Gypsum board false ceiling (recessed lighting, spotlights)\",\"Ceiling electrical wiring complete\"],\r\n[\"Drywall & False Ceiling\",\"Gypsum board partition walls (if required)\",\"Interior partition layout finalized\"],\r\n[\"Doors & Windows\",\"Install interior door frames / jambs\",\"Plastering and wall preparation complete\"],\r\n[\"Doors & Windows\",\"Install interior doors\",\"Door frames installed\"],\r\n[\"Doors & Windows\",\"Install main entrance security door\",\"Entrance door frame installed\"],\r\n[\"Doors & Windows\",\"Install windows and glazing (UPVC / aluminum)\",\"Exterior facade finishing complete\"],\r\n[\"Painting\",\"Wall and ceiling filler / putty application\",\"Wall joints finished and plaster dry\"],\r\n[\"Painting\",\"Primer coat on walls and ceilings\",\"Filler applied and sanded\"],\r\n[\"Painting\",\"Final top coat on walls and ceilings\",\"Primer coat complete\"],\r\n[\"Painting\",\"Decorative wall finishes (patina, calligraphy, and murals)\",\"Final top coat on walls and ceilings complete\"],\r\n[\"Painting\",\"Painting doors and frames\",\"Doors installed\"],\r\n[\"Electrical\",\"Final-fix electrical: switches and outlets\",\"Rough electrical wiring and wall painting complete\"],\r\n[\"Electrical\",\"Install ceiling light fixtures\",\"False ceiling and painting complete\"],\r\n[\"Electrical\",\"Install distribution panel and unit meter\",\"Wiring complete and inspector approval\"],\r\n[\"Mechanical (Plumbing & HVAC)\",\"Final-fix plumbing and faucet installation\",\"Rough plumbing and tiling complete\"],\r\n[\"Mechanical (Plumbing & HVAC)\",\"Install kitchen sink and bathroom basin\",\"Cabinets and countertop installed\"],\r\n[\"Mechanical (Plumbing & HVAC)\",\"Install toilet and bathroom fixtures\",\"Bathroom tiling and plumbing complete\"],\r\n[\"Mechanical (Plumbing & HVAC)\",\"Install boiler/heater and radiators\",\"Heating pipework and painting complete\"],\r\n[\"Mechanical (Plumbing & HVAC)\",\"Install split AC / cooling units\",\"Refrigerant line and outdoor unit location prepared\"],\r\n[\"Cabinetry & Millwork\",\"Install kitchen cabinets\",\"Kitchen tiling and painting complete\"],\r\n[\"Cabinetry & Millwork\",\"Install kitchen countertop (stone / quartz)\",\"Cabinet carcasses installed\"],\r\n[\"Cabinetry & Millwork\",\"Install wardrobes and MDF built-ins\",\"Room painting complete\"],\r\n[\"Miscellaneous Finishing\",\"Install railings and balustrades (balcony, staircase)\",\"Stone work on stairs/balcony complete\"],\r\n[\"Miscellaneous Finishing\",\"Install mirrors and bathroom vanity stone\",\"Bathroom tiling complete\"],\r\n[\"Miscellaneous Finishing\",\"Install electric shutters / curtain tracks\",\"Windows installed\"],\r\n[\"Miscellaneous Finishing\",\"Install video intercom and security cameras\",\"Related wiring done during electrical final-fix\"],\r\n[\"Cleaning & Handover\",\"Rough clean (after all construction work)\",\"All above works complete\"],\r\n[\"Cleaning & Handover\",\"Snag list / defect rectification\",\"Joint inspection with supervisor / client\"],\r\n[\"Cleaning & Handover\",\"Final detailed cleaning\",\"Snag list items resolved\"],\r\n[\"Cleaning & Handover\",\"Provisional handover to client / owner\",\"Final cleaning and quality approval\"],\r\n[\"Cleaning & Handover\",\"Final handover and warranty documentation\",\"Provisional handover issues resolved\"]\r\n];\r\n\r\nfunction todayStr(){ return new Date().toISOString().slice(0,10); }\r\nfunction formatDate(d){\r\n  if(!d) return '';\r\n  const dt = new Date(d + 'T00:00:00');\r\n  if(isNaN(dt)) return d;\r\n  return dt.toLocaleDateString(undefined, { year:'numeric', month:'long', day:'numeric' });\r\n}\r\n\r\nfunction reportTypeLabel(type){\r\n  return type === 'status' ? 'Detailed status report' : type === 'timeline' ? 'Timeline (Gantt)' : 'Checklist report';\r\n}\r\nfunction uid(){ return 'x' + Date.now().toString(36) + Math.random().toString(36).slice(2,8); }\r\nfunction escapeHtml(s){ return (s||'').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])); }\r\nfunction showToast(msg){\r\n  const t = document.getElementById('toast');\r\n  t.textContent = msg; t.classList.add('show');\r\n  setTimeout(()=> t.classList.remove('show'), 1500);\r\n}\r\n\r\n/* ================= Navigation ================= */\r\nfunction showHome(){\r\n  currentSpace = null; tasks = []; photoCache = {};\r\n  document.getElementById('backBtn').style.display = 'none';\r\n  document.getElementById('headerTitle').textContent = 'Site Finishing Tracker';\r\n  document.getElementById('headerSub').textContent = 'Select or create a space to begin';\r\n  document.getElementById('progressWrap').style.display = 'none';\r\n  document.getElementById('barTrack').style.display = 'none';\r\n  document.getElementById('spaceToolbar').style.display = 'none';\r\n  document.getElementById('homeToolbar').style.display = 'flex';\r\n  document.getElementById('filters').style.display = 'none';\r\n  document.getElementById('addBtn').textContent = '+ Add new space';\r\n  document.getElementById('reportView').classList.remove('open');\r\n  document.getElementById('historyView').classList.remove('open');\r\n  document.getElementById('homeSort').style.display = 'flex';\r\n  document.querySelectorAll('#homeSort .chip').forEach(c => c.classList.toggle('active', c.dataset.sort === sortMode));\r\n  document.getElementById('homeSortHint').style.display = sortMode === 'manual' ? 'inline' : 'none';\r\n  editMode = false;\r\n  selectedSpaceIds = new Set();\r\n  updateEditUI();\r\n  renderHome();\r\n}\r\n\r\nasync function updateEditUI(){\r\n  document.getElementById('editSpacesBtn').textContent = editMode ? 'Done' : 'Edit';\r\n  document.getElementById('selectAllBtn').style.display = editMode ? 'inline-block' : 'none';\r\n  document.getElementById('homeSort').style.display = editMode ? 'none' : 'flex';\r\n  document.getElementById('addBtn').style.display = editMode ? 'none' : 'block';\r\n  const delBtn = document.getElementById('deleteSelectedBtn');\r\n  delBtn.style.display = editMode ? 'block' : 'none';\r\n  delBtn.disabled = selectedSpaceIds.size === 0;\r\n  delBtn.textContent = selectedSpaceIds.size ? `Delete (${selectedSpaceIds.size})` : 'Delete';\r\n  if(editMode){\r\n    const total = (await dbGetAll('spaces')).length;\r\n    document.getElementById('selectAllBtn').textContent = (total > 0 && selectedSpaceIds.size === total) ? 'Deselect all' : 'Select all';\r\n  }\r\n}\r\n\r\nasync function openSpace(spaceId){\r\n  const space = await dbGet('spaces', spaceId);\r\n  if(!space) return;\r\n  if(!space.reportDate){ space.reportDate = todayStr(); await dbPut('spaces', space); }\r\n  currentSpace = space;\r\n  tasks = await dbGetAllByIndex('tasks', 'spaceId', spaceId);\r\n  photoCache = {};\r\n  const withPhoto = tasks.filter(t => t.hasPhoto);\r\n  await Promise.all(withPhoto.map(async t => {\r\n    const p = await dbGet('photos', t.id);\r\n    if(p) photoCache[t.id] = p.dataUrl;\r\n  }));\r\n  document.getElementById('backBtn').style.display = 'inline-block';\r\n  document.getElementById('headerTitle').textContent = space.name;\r\n  document.getElementById('headerSub').textContent = 'Report date: ' + formatDate(space.reportDate);\r\n  document.getElementById('progressWrap').style.display = 'block';\r\n  document.getElementById('barTrack').style.display = 'block';\r\n  document.getElementById('spaceToolbar').style.display = 'flex';\r\n  document.getElementById('homeToolbar').style.display = 'none';\r\n  document.getElementById('filters').style.display = 'flex';\r\n  document.getElementById('addBtn').textContent = '+ Add new task';\r\n  document.getElementById('reportView').classList.remove('open');\r\n  document.getElementById('historyView').classList.remove('open');\r\n  document.getElementById('homeSort').style.display = 'none';\r\n  currentFilter = 'all';\r\n  currentSearch = '';\r\n  document.getElementById('taskSearch').value = '';\r\n  document.getElementById('searchClear').style.display = 'none';\r\n  document.querySelectorAll('.chip').forEach(c => c.classList.toggle('active', c.dataset.f === 'all'));\r\n  renderSpace();\r\n}\r\n\r\n/* ================= Home (space list) ================= */\r\nasync function renderHome(){\r\n  const spaces = await dbGetAll('spaces');\r\n  const main = document.getElementById('main');\r\n  main.innerHTML = '';\r\n  if(spaces.length === 0){\r\n    main.innerHTML = '<div class=\"empty\">No spaces yet. Tap \"+ Add new space\" to create your first one (e.g. a room, unit, or floor).</div>';\r\n    return;\r\n  }\r\n  if(sortMode === 'name'){\r\n    spaces.sort((a,b) => a.name.localeCompare(b.name));\r\n  } else if(sortMode === 'reportDate'){\r\n    spaces.sort((a,b) => (b.reportDate||'').localeCompare(a.reportDate||''));\r\n  } else {\r\n    spaces.sort((a,b) => (a.order ?? a.createdAt ?? 0) - (b.order ?? b.createdAt ?? 0));\r\n  }\r\n  for(const s of spaces){\r\n    const spaceTasks = await dbGetAllByIndex('tasks', 'spaceId', s.id);\r\n    const total = spaceTasks.length;\r\n    const done = spaceTasks.filter(t=>t.status==='done').length;\r\n    const pct = total ? Math.round((done/total)*100) : 0;\r\n    const isSelected = selectedSpaceIds.has(s.id);\r\n    const card = document.createElement('div');\r\n    card.className = 'space-card' + (isSelected ? ' selected' : '');\r\n    card.dataset.id = s.id;\r\n    card.innerHTML = `\r\n      ${editMode ? `<span class=\"select-circle${isSelected ? ' checked' : ''}\">${isSelected ? '&#10003;' : ''}</span>` : ''}\r\n      ${!editMode && sortMode === 'manual' ? '<span class=\"drag-handle\">&#9776;</span>' : ''}\r\n      <div class=\"space-card-body\">\r\n        <h3>${escapeHtml(s.name)}</h3>\r\n        <div class=\"meta\"><span>${done} of ${total} done</span><span>${pct}%</span></div>\r\n        <div class=\"mini-bar\"><div class=\"mini-fill\" style=\"width:${pct}%\"></div></div>\r\n      </div>\r\n    `;\r\n    card.addEventListener('click', () => {\r\n      if(editMode){\r\n        if(selectedSpaceIds.has(s.id)) selectedSpaceIds.delete(s.id);\r\n        else selectedSpaceIds.add(s.id);\r\n        updateEditUI();\r\n        renderHome();\r\n      } else {\r\n        openSpace(s.id);\r\n      }\r\n    });\r\n    main.appendChild(card);\r\n  }\r\n  if(!editMode && sortMode === 'manual') wireDragReorder(main, spaces);\r\n}\r\n\r\nasync function deleteSpace(spaceId){\r\n  const spaceTasks = await dbGetAllByIndex('tasks', 'spaceId', spaceId);\r\n  for(const t of spaceTasks){\r\n    await dbDelete('tasks', t.id);\r\n    if(t.hasPhoto) await dbDelete('photos', t.id).catch(()=>{});\r\n  }\r\n  const history = await dbGetAllByIndex('reportHistory', 'spaceId', spaceId);\r\n  for(const h of history) await dbDelete('reportHistory', h.id);\r\n  await dbDelete('spaces', spaceId);\r\n}\r\n\r\nfunction wireDragReorder(main, spaces){\r\n  // Uses Pointer Events (not the HTML5 Drag and Drop API) because native\r\n  // drag-and-drop only fires from a mouse - touch screens never trigger\r\n  // dragstart/dragover/drop, so on mobile the finger just scrolls the page.\r\n  // Move/up listeners are attached to window for the duration of the drag\r\n  // (rather than relying on setPointerCapture) so the gesture keeps working\r\n  // even if the finger slides off the small handle element.\r\n  const CARD_GAP = 10; // must match .space-card margin-bottom\r\n  const allCards = () => [...main.querySelectorAll('.space-card')];\r\n\r\n  main.querySelectorAll('.space-card').forEach(card => {\r\n    const handle = card.querySelector('.drag-handle');\r\n    if(!handle) return;\r\n\r\n    handle.addEventListener('click', e => e.stopPropagation());\r\n\r\n    handle.addEventListener('pointerdown', e => {\r\n      if(e.button !== undefined && e.button !== 0) return;\r\n      e.preventDefault();\r\n      const pointerId = e.pointerId;\r\n      const startY = e.clientY;\r\n      const cardHeight = card.offsetHeight + CARD_GAP;\r\n      const originalIndex = allCards().indexOf(card);\r\n      let currentIndex = originalIndex;\r\n      let moved = false;\r\n\r\n      card.classList.add('dragging');\r\n      card.style.position = 'relative';\r\n      card.style.zIndex = '10';\r\n      allCards().forEach(c => { if(c !== card) c.style.transition = 'transform .15s ease'; });\r\n\r\n      function onMove(ev){\r\n        if(ev.pointerId !== pointerId) return;\r\n        const deltaY = ev.clientY - startY;\r\n        if(Math.abs(deltaY) > 3) moved = true;\r\n        card.style.transform = `translateY(${deltaY}px)`;\r\n        const steps = Math.round(deltaY / cardHeight);\r\n        const newIndex = Math.min(allCards().length - 1, Math.max(0, originalIndex + steps));\r\n        if(newIndex !== currentIndex){\r\n          allCards().forEach((c, i) => {\r\n            if(c === card) return;\r\n            let shift = 0;\r\n            if(newIndex > originalIndex && i > originalIndex && i <= newIndex) shift = -1;\r\n            else if(newIndex < originalIndex && i >= newIndex && i < originalIndex) shift = 1;\r\n            c.style.transform = shift ? `translateY(${shift * cardHeight}px)` : '';\r\n          });\r\n          currentIndex = newIndex;\r\n        }\r\n      }\r\n\r\n      async function onUp(ev){\r\n        if(ev.pointerId !== pointerId) return;\r\n        window.removeEventListener('pointermove', onMove);\r\n        window.removeEventListener('pointerup', onUp);\r\n        window.removeEventListener('pointercancel', onUp);\r\n        card.classList.remove('dragging');\r\n        card.style.position = '';\r\n        card.style.zIndex = '';\r\n        card.style.transform = '';\r\n\r\n        const cards = allCards();\r\n        const draggedId = card.dataset.id;\r\n        const ids = cards.filter(c => c !== card).map(c => c.dataset.id);\r\n        ids.splice(currentIndex, 0, draggedId);\r\n        cards.forEach(c => { c.style.transform = ''; c.style.transition = ''; });\r\n\r\n        if(!moved) return;\r\n        await Promise.all(ids.map((id, i) => {\r\n          const sp = spaces.find(s => s.id === id);\r\n          sp.order = i;\r\n          return dbPut('spaces', sp);\r\n        }));\r\n        showToast('Order updated');\r\n        renderHome();\r\n      }\r\n\r\n      window.addEventListener('pointermove', onMove);\r\n      window.addEventListener('pointerup', onUp);\r\n      window.addEventListener('pointercancel', onUp);\r\n    });\r\n  });\r\n}\r\n\r\n/* ================= Space checklist ================= */\r\nfunction updateProgress(){\r\n  const total = tasks.length;\r\n  const done = tasks.filter(t=>t.status==='done').length;\r\n  const inprog = tasks.filter(t=>t.status==='inprogress').length;\r\n  const pct = total ? Math.round((done/total)*100) : 0;\r\n  document.getElementById('progressNum').textContent = pct + '%';\r\n  document.getElementById('progressLabel').textContent = `${done} of ${total} done`;\r\n  document.getElementById('barFill').style.width = pct + '%';\r\n}\r\n\r\nfunction groupByCategory(list){\r\n  const map = new Map();\r\n  list.forEach(t => { if(!map.has(t.category)) map.set(t.category, []); map.get(t.category).push(t); });\r\n  return map;\r\n}\r\n\r\nfunction renderSpace(){\r\n  updateProgress();\r\n  const main = document.getElementById('main');\r\n  main.innerHTML = '';\r\n  let filtered = currentFilter === 'all' ? tasks : tasks.filter(t => t.status === currentFilter);\r\n  if(currentSearch){\r\n    const q = currentSearch;\r\n    filtered = filtered.filter(t =>\r\n      (t.task||'').toLowerCase().includes(q) ||\r\n      (t.category||'').toLowerCase().includes(q) ||\r\n      (t.prereq||'').toLowerCase().includes(q) ||\r\n      (t.notes||'').toLowerCase().includes(q)\r\n    );\r\n  }\r\n  if(filtered.length === 0){\r\n    main.innerHTML = currentSearch\r\n      ? '<div class=\"empty\">No tasks match your search.</div>'\r\n      : '<div class=\"empty\">No tasks in this status.</div>';\r\n    return;\r\n  }\r\n  const groups = groupByCategory(filtered);\r\n  groups.forEach((items, category) => {\r\n    const h = document.createElement('div');\r\n    h.className = 'cat-heading';\r\n    h.innerHTML = `<span>${escapeHtml(category)}</span><span class=\"cat-count\">${items.length}</span>`;\r\n    main.appendChild(h);\r\n    items.forEach(t => main.appendChild(renderCard(t)));\r\n  });\r\n}\r\n\r\nfunction scheduleSaveTask(t){\r\n  clearTimeout(saveTimers[t.id]);\r\n  saveTimers[t.id] = setTimeout(async () => {\r\n    try{ await dbPut('tasks', t); }catch(e){ showToast('Save failed'); }\r\n  }, 400);\r\n}\r\n\r\nfunction renderCard(t){\r\n  const card = document.createElement('div');\r\n  card.className = 'card status-' + t.status;\r\n  card.dataset.id = t.id;\r\n  card.innerHTML = `\r\n    <div class=\"card-head\">\r\n      <textarea class=\"task-title\" rows=\"1\" data-field=\"task\">${escapeHtml(t.task)}</textarea>\r\n      <button class=\"del-btn\" title=\"Delete\">&#10005;</button>\r\n    </div>\r\n    <input class=\"cat-select\" data-field=\"category\" value=\"${escapeHtml(t.category)}\" placeholder=\"Category\">\r\n    <label class=\"field-label\">Prerequisite (notes)</label>\r\n    <textarea class=\"prereq-input\" data-field=\"prereq\" rows=\"1\" placeholder=\"What needs to be done before this task?\">${escapeHtml(t.prereq)}</textarea>\r\n    <label class=\"field-label\">Depends on (for Timeline)</label>\r\n    <div class=\"dep-chips\">\r\n      ${(t.prereqIds||[]).map(depId => {\r\n        const depTask = tasks.find(x => x.id === depId);\r\n        return depTask ? `<span class=\"dep-chip\">${escapeHtml(depTask.task)}<button class=\"dep-remove\" data-dep-id=\"${depId}\" title=\"Remove dependency\">&times;</button></span>` : '';\r\n      }).join('')}\r\n      <button class=\"dep-add-btn\" type=\"button\">+ Add dependency</button>\r\n    </div>\r\n    <div class=\"status-row\">\r\n      <div class=\"status-btn\" data-s=\"notstarted\">Not started</div>\r\n      <div class=\"status-btn\" data-s=\"inprogress\">In progress</div>\r\n      <div class=\"status-btn\" data-s=\"done\">Completed</div>\r\n    </div>\r\n    <div class=\"date-row\">\r\n      <div class=\"date-field\"><label class=\"field-label\">Start date</label><input type=\"date\" data-field=\"startDate\" value=\"${t.startDate||''}\"></div>\r\n      <div class=\"date-field\"><label class=\"field-label\">End date</label><input type=\"date\" data-field=\"endDate\" value=\"${t.endDate||''}\"></div>\r\n    </div>\r\n    <label class=\"field-label\">Final notes</label>\r\n    <textarea class=\"notes-input\" data-field=\"notes\" placeholder=\"Notes, defects, or handover remarks...\">${escapeHtml(t.notes)}</textarea>\r\n    <div class=\"photo-row\">\r\n      ${photoCache[t.id] ? `\r\n        <div class=\"photo-thumb-wrap\">\r\n          <img class=\"photo-thumb\" src=\"${photoCache[t.id]}\">\r\n          <button class=\"photo-remove-btn\" title=\"Remove photo\">&times;</button>\r\n        </div>\r\n      ` : ''}\r\n      <label class=\"photo-btn\">&#128247; ${photoCache[t.id] ? 'Change photo' : 'Add photo'}<input type=\"file\" accept=\"image/*\" class=\"photo-input\"></label>\r\n    </div>\r\n  `;\r\n\r\n  card.querySelectorAll('.status-btn').forEach(btn => {\r\n    if(btn.dataset.s === t.status) btn.classList.add('sel');\r\n    btn.addEventListener('click', () => {\r\n      t.status = btn.dataset.s;\r\n      card.className = 'card status-' + t.status;\r\n      card.querySelectorAll('.status-btn').forEach(b => b.classList.toggle('sel', b.dataset.s === t.status));\r\n      updateProgress();\r\n      scheduleSaveTask(t);\r\n    });\r\n  });\r\n  card.querySelector('[data-field=\"task\"]').addEventListener('input', e => { t.task = e.target.value; scheduleSaveTask(t); });\r\n  card.querySelector('[data-field=\"category\"]').addEventListener('change', e => { t.category = e.target.value || 'Uncategorized'; scheduleSaveTask(t); renderSpace(); });\r\n  card.querySelector('[data-field=\"prereq\"]').addEventListener('input', e => { t.prereq = e.target.value; scheduleSaveTask(t); });\r\n  card.querySelector('[data-field=\"notes\"]').addEventListener('input', e => { t.notes = e.target.value; scheduleSaveTask(t); });\r\n  card.querySelector('[data-field=\"startDate\"]').addEventListener('change', e => { t.startDate = e.target.value; scheduleSaveTask(t); });\r\n  card.querySelector('[data-field=\"endDate\"]').addEventListener('change', e => { t.endDate = e.target.value; scheduleSaveTask(t); });\r\n\r\n  card.querySelector('.dep-add-btn').addEventListener('click', () => openDepPicker(t.id));\r\n  card.querySelectorAll('.dep-remove').forEach(btn => {\r\n    btn.addEventListener('click', async () => {\r\n      t.prereqIds = (t.prereqIds||[]).filter(id => id !== btn.dataset.depId);\r\n      await dbPut('tasks', t);\r\n      renderSpace();\r\n    });\r\n  });\r\n\r\n  card.querySelector('.del-btn').addEventListener('click', async () => {\r\n    if(!confirm('Delete this task?')) return;\r\n    tasks = tasks.filter(x => x.id !== t.id);\r\n    delete photoCache[t.id];\r\n    await dbDelete('tasks', t.id);\r\n    if(t.hasPhoto) await dbDelete('photos', t.id).catch(()=>{});\r\n    for(const other of tasks){\r\n      if(other.prereqIds && other.prereqIds.includes(t.id)){\r\n        other.prereqIds = other.prereqIds.filter(id => id !== t.id);\r\n        await dbPut('tasks', other);\r\n      }\r\n    }\r\n    renderSpace();\r\n  });\r\n\r\n  card.querySelector('.photo-input').addEventListener('change', e => handlePhotoUpload(e, t));\r\n  const thumb = card.querySelector('.photo-thumb');\r\n  if(thumb) thumb.addEventListener('click', () => openLightbox(photoCache[t.id]));\r\n  const removeBtn = card.querySelector('.photo-remove-btn');\r\n  if(removeBtn) removeBtn.addEventListener('click', async e => {\r\n    e.stopPropagation();\r\n    if(!confirm('Remove this photo?')) return;\r\n    delete photoCache[t.id];\r\n    t.hasPhoto = false;\r\n    await dbDelete('photos', t.id).catch(()=>{});\r\n    await dbPut('tasks', t);\r\n    renderSpace();\r\n  });\r\n\r\n  return card;\r\n}\r\n\r\nfunction handlePhotoUpload(e, t){\r\n  const file = e.target.files[0];\r\n  if(!file) return;\r\n  const reader = new FileReader();\r\n  reader.onload = evt => {\r\n    const img = new Image();\r\n    img.onload = async () => {\r\n      const maxW = 700;\r\n      const scale = Math.min(1, maxW / img.width);\r\n      const canvas = document.createElement('canvas');\r\n      canvas.width = img.width * scale; canvas.height = img.height * scale;\r\n      const ctx = canvas.getContext('2d');\r\n      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);\r\n      const dataUrl = canvas.toDataURL('image/jpeg', 0.6);\r\n      try{\r\n        await dbPut('photos', { taskId: t.id, dataUrl });\r\n        photoCache[t.id] = dataUrl;\r\n        t.hasPhoto = true;\r\n        await dbPut('tasks', t);\r\n        renderSpace();\r\n      }catch(err){ showToast('Photo could not be saved'); }\r\n    };\r\n    img.src = evt.target.result;\r\n  };\r\n  reader.readAsDataURL(file);\r\n}\r\n\r\nfunction openLightbox(src){\r\n  if(!src) return;\r\n  document.getElementById('lbImg').src = src;\r\n  document.getElementById('lightbox').classList.add('open');\r\n}\r\ndocument.getElementById('lbClose').addEventListener('click', () => document.getElementById('lightbox').classList.remove('open'));\r\ndocument.getElementById('lightbox').addEventListener('click', e => { if(e.target.id === 'lightbox') document.getElementById('lightbox').classList.remove('open'); });\r\n\r\ndocument.getElementById('homeSort').addEventListener('click', e => {\r\n  const chip = e.target.closest('.chip');\r\n  if(!chip) return;\r\n  document.querySelectorAll('#homeSort .chip').forEach(c => c.classList.remove('active'));\r\n  chip.classList.add('active');\r\n  sortMode = chip.dataset.sort;\r\n  localStorage.setItem('spaceSortMode', sortMode);\r\n  document.getElementById('homeSortHint').style.display = sortMode === 'manual' ? 'inline' : 'none';\r\n  renderHome();\r\n});\r\ndocument.getElementById('filters').addEventListener('click', e => {\r\n  const chip = e.target.closest('.chip');\r\n  if(!chip) return;\r\n  document.querySelectorAll('.chip').forEach(c => c.classList.remove('active'));\r\n  chip.classList.add('active');\r\n  currentFilter = chip.dataset.f;\r\n  renderSpace();\r\n});\r\ndocument.getElementById('taskSearch').addEventListener('input', e => {\r\n  currentSearch = e.target.value.trim().toLowerCase();\r\n  document.getElementById('searchClear').style.display = currentSearch ? 'block' : 'none';\r\n  renderSpace();\r\n});\r\ndocument.getElementById('searchClear').addEventListener('click', () => {\r\n  const input = document.getElementById('taskSearch');\r\n  input.value = '';\r\n  currentSearch = '';\r\n  document.getElementById('searchClear').style.display = 'none';\r\n  renderSpace();\r\n  input.focus();\r\n});\r\n\r\ndocument.getElementById('backBtn').addEventListener('click', showHome);\r\n\r\n/* ================= Add space / add task ================= */\r\ndocument.getElementById('addBtn').addEventListener('click', () => {\r\n  if(!currentSpace){\r\n    openModal('New space', '', async name => {\r\n      if(!name) return;\r\n      const space = { id: uid(), name, createdAt: Date.now(), order: Date.now(), reportDate: todayStr() };\r\n      await dbPut('spaces', space);\r\n      for(const [category, task, prereq] of DEFAULT_TASKS){\r\n        await dbPut('tasks', { id: uid(), spaceId: space.id, category, task, prereq, prereqIds:[], status:'notstarted', notes:'', startDate:'', endDate:'', hasPhoto:false });\r\n      }\r\n      showToast('Space created');\r\n      openSpace(space.id);\r\n    });\r\n  } else {\r\n    (async () => {\r\n      const t = { id: uid(), spaceId: currentSpace.id, category:'New Task', task:'Enter task description', prereq:'', prereqIds:[], status:'notstarted', notes:'', startDate:'', endDate:'', hasPhoto:false };\r\n      await dbPut('tasks', t);\r\n      tasks.push(t);\r\n      renderSpace();\r\n      setTimeout(() => {\r\n        const el = document.querySelector(`.card[data-id=\"${t.id}\"] .task-title`);\r\n        if(el){ el.focus(); el.select(); el.scrollIntoView({behavior:'smooth', block:'center'}); }\r\n      }, 50);\r\n    })();\r\n  }\r\n});\r\n\r\ndocument.getElementById('renameSpaceBtn').addEventListener('click', () => {\r\n  openModal('Rename space', currentSpace.name, async name => {\r\n    if(!name) return;\r\n    currentSpace.name = name;\r\n    await dbPut('spaces', currentSpace);\r\n    document.getElementById('headerTitle').textContent = name;\r\n  });\r\n});\r\n\r\ndocument.getElementById('reportDateBtn').addEventListener('click', () => {\r\n  openModal('Report date', currentSpace.reportDate || todayStr(), async val => {\r\n    if(!val) return;\r\n    currentSpace.reportDate = val;\r\n    await dbPut('spaces', currentSpace);\r\n    document.getElementById('headerSub').textContent = 'Report date: ' + formatDate(val);\r\n  }, 'date');\r\n});\r\n\r\n/* ================= Modal ================= */\r\nfunction openModal(title, initial, onConfirm, type){\r\n  document.getElementById('modalTitle').textContent = title;\r\n  const input = document.getElementById('modalInput');\r\n  input.type = type || 'text';\r\n  input.placeholder = type === 'date' ? '' : 'e.g. Unit 3 - Kitchen';\r\n  input.value = initial;\r\n  modalOnConfirm = onConfirm;\r\n  document.getElementById('modalOverlay').classList.add('open');\r\n  setTimeout(() => input.focus(), 50);\r\n}\r\ndocument.getElementById('modalCancel').addEventListener('click', () => document.getElementById('modalOverlay').classList.remove('open'));\r\ndocument.getElementById('modalConfirm').addEventListener('click', () => {\r\n  const val = document.getElementById('modalInput').value.trim();\r\n  document.getElementById('modalOverlay').classList.remove('open');\r\n  if(modalOnConfirm) modalOnConfirm(val);\r\n});\r\ndocument.getElementById('modalInput').addEventListener('keydown', e => { if(e.key === 'Enter') document.getElementById('modalConfirm').click(); });\r\n\r\n/* ================= Dependency picker (structured prerequisites for Timeline/CPM) ================= */\r\nfunction openDepPicker(taskId){\r\n  depPickerTaskId = taskId;\r\n  const current = tasks.find(t => t.id === taskId);\r\n  const others = tasks.filter(t => t.id !== taskId);\r\n  const list = document.getElementById('depPickerList');\r\n  if(others.length === 0){\r\n    list.innerHTML = '<div class=\"empty\">No other tasks in this space yet.</div>';\r\n  } else {\r\n    list.innerHTML = others.map(t => `\r\n      <label class=\"dep-picker-item\">\r\n        <input type=\"checkbox\" value=\"${t.id}\" ${(current.prereqIds||[]).includes(t.id) ? 'checked' : ''}>\r\n        <span>${escapeHtml(t.task)} <span class=\"dep-picker-cat\">(${escapeHtml(t.category)})</span></span>\r\n      </label>\r\n    `).join('');\r\n  }\r\n  document.getElementById('depPickerOverlay').classList.add('open');\r\n}\r\ndocument.getElementById('depPickerCancel').addEventListener('click', () => document.getElementById('depPickerOverlay').classList.remove('open'));\r\ndocument.getElementById('depPickerConfirm').addEventListener('click', async () => {\r\n  const checked = [...document.querySelectorAll('#depPickerList input[type=checkbox]:checked')].map(cb => cb.value);\r\n  const t = tasks.find(x => x.id === depPickerTaskId);\r\n  if(t){\r\n    t.prereqIds = checked;\r\n    await dbPut('tasks', t);\r\n  }\r\n  document.getElementById('depPickerOverlay').classList.remove('open');\r\n  renderSpace();\r\n});\r\n\r\n/* ================= Excel export ================= */\r\ndocument.getElementById('exportExcelBtn').addEventListener('click', () => {\r\n  const rows = [['No.','Category / Phase','Task Description','Prerequisite','Status','Start Date','End Date','Final Notes']];\r\n  tasks.forEach((t,i) => rows.push([i+1, t.category, t.task, t.prereq, STATUS[t.status], t.startDate||'', t.endDate||'', t.notes||'']));\r\n  const ws = XLSX.utils.aoa_to_sheet(rows);\r\n  ws['!cols'] = [{wch:5},{wch:22},{wch:36},{wch:34},{wch:14},{wch:12},{wch:12},{wch:38}];\r\n  const wb = XLSX.utils.book_new();\r\n  XLSX.utils.book_append_sheet(wb, ws, 'Checklist');\r\n  const safeName = currentSpace.name.replace(/[^a-z0-9\\-_]+/gi, '_');\r\n  XLSX.writeFile(wb, `${safeName}-checklist.xlsx`);\r\n  showToast('Excel file downloaded');\r\n});\r\n\r\n/* ================= Excel import ================= */\r\nconst STATUS_FROM_LABEL = { 'not started':'notstarted', 'in progress':'inprogress', 'completed':'done', 'done':'done' };\r\nfunction parseStatusCell(v){\r\n  const s = (v||'').toString().trim().toLowerCase();\r\n  return STATUS_FROM_LABEL[s] || null;\r\n}\r\nfunction parseDateCell(v){\r\n  if(v instanceof Date && !isNaN(v)) return v.toISOString().slice(0,10);\r\n  if(typeof v === 'string'){\r\n    const s = v.trim();\r\n    if(!s) return '';\r\n    if(/^\\d{4}-\\d{2}-\\d{2}$/.test(s)) return s;\r\n    const d = new Date(s);\r\n    if(!isNaN(d)) return d.toISOString().slice(0,10);\r\n    return '';\r\n  }\r\n  return '';\r\n}\r\n\r\ndocument.getElementById('importExcelBtn').addEventListener('click', () => document.getElementById('importExcelInput').click());\r\ndocument.getElementById('importExcelInput').addEventListener('change', async e => {\r\n  const file = e.target.files[0];\r\n  e.target.value = '';\r\n  if(!file) return;\r\n  let rows;\r\n  try{\r\n    const buf = await file.arrayBuffer();\r\n    const wb = XLSX.read(buf, { type:'array', cellDates:true });\r\n    const ws = wb.Sheets[wb.SheetNames[0]];\r\n    rows = XLSX.utils.sheet_to_json(ws, { header:1, defval:'' });\r\n  }catch(err){\r\n    alert('This file could not be read as an Excel checklist.');\r\n    return;\r\n  }\r\n  const dataRows = rows.slice(1).filter(r => r.some(c => (c||'').toString().trim() !== ''));\r\n  if(dataRows.length === 0){\r\n    alert('No task rows were found in this file. Make sure it uses the same columns as \"Export Excel\" (No. / Category / Task Description / Prerequisite / Status / Start Date / End Date / Final Notes).');\r\n    return;\r\n  }\r\n  if(!confirm(`This will update matching tasks (by description) and add any new ones found in \"${file.name}\" (${dataRows.length} row(s)). Continue?`)) return;\r\n\r\n  const usedIds = new Set();\r\n  let updated = 0, created = 0, skipped = 0;\r\n  for(const row of dataRows){\r\n    const [, category, taskDesc, prereq, statusText, startDate, endDate, notes] = row;\r\n    const descTrim = (taskDesc||'').toString().trim();\r\n    if(!descTrim){ skipped++; continue; }\r\n    const statusKey = parseStatusCell(statusText);\r\n    const sDate = parseDateCell(startDate);\r\n    const eDate = parseDateCell(endDate);\r\n    const match = tasks.find(t => !usedIds.has(t.id) && t.task.trim().toLowerCase() === descTrim.toLowerCase());\r\n\r\n    if(match){\r\n      usedIds.add(match.id);\r\n      match.category = (category||'').toString().trim() || 'Uncategorized';\r\n      match.task = descTrim;\r\n      match.prereq = (prereq||'').toString().trim();\r\n      if(statusKey) match.status = statusKey;\r\n      match.startDate = sDate;\r\n      match.endDate = eDate;\r\n      match.notes = (notes||'').toString().trim();\r\n      await dbPut('tasks', match);\r\n      updated++;\r\n    } else {\r\n      const newTask = {\r\n        id: uid(), spaceId: currentSpace.id,\r\n        category: (category||'').toString().trim() || 'Uncategorized',\r\n        task: descTrim,\r\n        prereq: (prereq||'').toString().trim(),\r\n        prereqIds: [],\r\n        status: statusKey || 'notstarted',\r\n        notes: (notes||'').toString().trim(),\r\n        startDate: sDate, endDate: eDate, hasPhoto:false\r\n      };\r\n      await dbPut('tasks', newTask);\r\n      tasks.push(newTask);\r\n      created++;\r\n    }\r\n  }\r\n  renderSpace();\r\n  showToast(`Import complete: ${updated} updated, ${created} added${skipped ? ', ' + skipped + ' skipped' : ''}`);\r\n});\r\n\r\n/* ================= Printable report ================= */\r\nasync function saveReportSnapshot(html, type){\r\n  const existing = await dbGetAllByIndex('reportHistory', 'spaceId', currentSpace.id);\r\n  const match = existing.find(h => h.reportDate === currentSpace.reportDate && (h.type||'category') === type);\r\n  const entry = { id: uid(), spaceId: currentSpace.id, reportDate: currentSpace.reportDate, type };\r\n  entry.html = html;\r\n  entry.generatedAt = Date.now();\r\n  await dbPut('reportHistory', entry);\r\n}\r\n\r\nfunction openGeneratedReport(html){\r\n  document.getElementById('reportContent').innerHTML = html;\r\n  reportBackTarget = 'checklist';\r\n  document.getElementById('reportBack').textContent = '← Back to checklist';\r\n  document.getElementById('reportView').classList.add('open');\r\n  window.scrollTo(0,0);\r\n}\r\n\r\ndocument.getElementById('reportBtn').addEventListener('click', async () => {\r\n  const total = tasks.length;\r\n  const done = tasks.filter(t=>t.status==='done').length;\r\n  const inprog = tasks.filter(t=>t.status==='inprogress').length;\r\n  const notstarted = tasks.filter(t=>t.status==='notstarted').length;\r\n  const groups = groupByCategory(tasks);\r\n\r\n  let html = `\r\n    <div class=\"report-header\">\r\n      <h1>${escapeHtml(currentSpace.name)} &mdash; Finishing Report</h1>\r\n      <div class=\"meta\">Report date: ${formatDate(currentSpace.reportDate || todayStr())} &middot; ${total} tasks</div>\r\n    </div>\r\n    <div class=\"report-summary\">\r\n      <span><b>${done}</b> completed</span>\r\n      <span><b>${inprog}</b> in progress</span>\r\n      <span><b>${notstarted}</b> not started</span>\r\n    </div>\r\n  `;\r\n  groups.forEach((items, category) => {\r\n    html += `<div class=\"report-cat\">${escapeHtml(category)}</div>`;\r\n    items.forEach(t => {\r\n      const badgeClass = t.status === 'done' ? 'rb-done' : t.status === 'inprogress' ? 'rb-inprogress' : 'rb-notstarted';\r\n      html += `<div class=\"report-item\">\r\n        <div class=\"rt-title\">${escapeHtml(t.task)}<span class=\"report-badge ${badgeClass}\">${STATUS[t.status]}</span></div>\r\n        ${t.prereq ? `<div class=\"rt-line\"><b>Prerequisite:</b> ${escapeHtml(t.prereq)}</div>` : ''}\r\n        ${t.startDate ? `<div class=\"rt-line\"><b>Start date:</b> ${t.startDate}</div>` : ''}\r\n        ${t.endDate ? `<div class=\"rt-line\"><b>End date:</b> ${t.endDate}</div>` : ''}\r\n        ${t.notes ? `<div class=\"rt-line\"><b>Notes:</b> ${escapeHtml(t.notes)}</div>` : ''}\r\n        ${photoCache[t.id] ? `<img src=\"${photoCache[t.id]}\">` : ''}\r\n      </div>`;\r\n    });\r\n  });\r\n  await saveReportSnapshot(html, 'category');\r\n  openGeneratedReport(html);\r\n});\r\n\r\n/* ================= Detailed status (narrative) report ================= */\r\ndocument.getElementById('statusReportBtn').addEventListener('click', async () => {\r\n  const total = tasks.length;\r\n  const sections = [\r\n    { key:'done', title:'Completed', className:'sh-done' },\r\n    { key:'inprogress', title:'In Progress', className:'sh-inprogress' },\r\n    { key:'notstarted', title:'Not Started', className:'sh-notstarted' },\r\n  ];\r\n\r\n  let html = `\r\n    <div class=\"report-header\">\r\n      <h1>${escapeHtml(currentSpace.name)} &mdash; Detailed Status Report</h1>\r\n      <div class=\"meta\">Report date: ${formatDate(currentSpace.reportDate || todayStr())} &middot; ${total} tasks</div>\r\n    </div>\r\n  `;\r\n  sections.forEach(sec => {\r\n    const items = tasks.filter(t => t.status === sec.key);\r\n    html += `<div class=\"report-status-section\">\r\n      <h2 class=\"report-status-heading ${sec.className}\">${sec.title} (${items.length})</h2>`;\r\n    if(items.length === 0){\r\n      html += `<p class=\"report-status-empty\">No tasks in this status.</p>`;\r\n    } else {\r\n      items.forEach(t => {\r\n        const parts = [];\r\n        if(t.prereq) parts.push(`Prerequisite: ${escapeHtml(t.prereq)}.`);\r\n        if(t.startDate) parts.push(`Started ${t.startDate}.`);\r\n        if(t.endDate) parts.push(`Finished ${t.endDate}.`);\r\n        if(t.notes) parts.push(`Notes: ${escapeHtml(t.notes)}.`);\r\n        html += `<p class=\"report-status-item\">\r\n          <b>${escapeHtml(t.task)}</b> <span class=\"rt-cat\">(${escapeHtml(t.category)})</span>.\r\n          ${parts.join(' ')}\r\n          ${photoCache[t.id] ? `<br><img src=\"${photoCache[t.id]}\">` : ''}\r\n        </p>`;\r\n      });\r\n    }\r\n    html += `</div>`;\r\n  });\r\n  await saveReportSnapshot(html, 'status');\r\n  openGeneratedReport(html);\r\n});\r\n\r\n/* ================= Timeline (Gantt) report ================= */\r\ndocument.getElementById('timelineBtn').addEventListener('click', async () => {\r\n  const total = tasks.length;\r\n  const withDates = tasks.filter(t => t.startDate && t.endDate).sort((a,b) => a.startDate.localeCompare(b.startDate));\r\n\r\n  let html = `\r\n    <div class=\"report-header\">\r\n      <h1>${escapeHtml(currentSpace.name)} &mdash; Timeline</h1>\r\n      <div class=\"meta\">Report date: ${formatDate(currentSpace.reportDate || todayStr())} &middot; ${withDates.length} of ${total} tasks have both a start and end date</div>\r\n    </div>\r\n  `;\r\n\r\n  if(withDates.length === 0){\r\n    html += `<p class=\"report-status-empty\">No tasks have both a start date and an end date yet, so a timeline can't be drawn. Add dates on the tasks you want to see here, then generate this again.</p>`;\r\n  } else {\r\n    const dayMs = 86400000;\r\n    const minMs = Math.min(...withDates.map(t => new Date(t.startDate+'T00:00:00').getTime()));\r\n    const maxMs = Math.max(...withDates.map(t => new Date(t.endDate+'T00:00:00').getTime()));\r\n    const totalDays = Math.max(1, Math.round((maxMs - minMs) / dayMs) + 1);\r\n    const dayWidth = totalDays > 90 ? 10 : totalDays > 45 ? 16 : 26;\r\n    const rowHeight = 34;\r\n    const chartWidth = totalDays * dayWidth;\r\n    const tickEvery = totalDays > 120 ? 30 : totalDays > 45 ? 14 : totalDays > 14 ? 7 : 1;\r\n\r\n    let ticks = '';\r\n    for(let d = 0; d < totalDays; d += tickEvery){\r\n      const dt = new Date(minMs + d * dayMs);\r\n      const label = dt.toLocaleDateString(undefined, { month:'short', day:'numeric' });\r\n      ticks += `<div class=\"gantt-tick\" style=\"left:${d*dayWidth}px;\">${label}</div>`;\r\n    }\r\n\r\n    let barsHtml = '';\r\n    let labelsHtml = '';\r\n    withDates.forEach((t, i) => {\r\n      const startOffset = Math.round((new Date(t.startDate+'T00:00:00').getTime() - minMs) / dayMs);\r\n      const endOffset = Math.round((new Date(t.endDate+'T00:00:00').getTime() - minMs) / dayMs);\r\n      const barWidth = Math.max(dayWidth * 0.7, (endOffset - startOffset + 1) * dayWidth - 2);\r\n      const barLeft = startOffset * dayWidth + 1;\r\n      const statusClass = t.status === 'done' ? 'gantt-done' : t.status === 'inprogress' ? 'gantt-inprogress' : 'gantt-notstarted';\r\n      const top = i * rowHeight + 6;\r\n      barsHtml += `<div class=\"gantt-bar ${statusClass}\" style=\"top:${top}px; left:${barLeft}px; width:${barWidth}px;\" title=\"${escapeHtml(t.task)}: ${t.startDate} to ${t.endDate}\">\r\n        <span class=\"gantt-bar-label\">${escapeHtml(t.task)}</span>\r\n      </div>`;\r\n      labelsHtml += `<div class=\"gantt-label-row\" title=\"${escapeHtml(t.task)}\">${escapeHtml(t.task)}</div>`;\r\n    });\r\n\r\n    html += `\r\n      <div class=\"gantt-legend\">\r\n        <span><span class=\"gantt-swatch gantt-done\"></span>Completed</span>\r\n        <span><span class=\"gantt-swatch gantt-inprogress\"></span>In progress</span>\r\n        <span><span class=\"gantt-swatch gantt-notstarted\"></span>Not started</span>\r\n      </div>\r\n      <div class=\"gantt-wrap\">\r\n        <div class=\"gantt-labels\">\r\n          <div class=\"gantt-label-header\">Task</div>\r\n          ${labelsHtml}\r\n        </div>\r\n        <div class=\"gantt-scroll\">\r\n          <div style=\"width:${chartWidth}px;\">\r\n            <div class=\"gantt-ticks\" style=\"width:${chartWidth}px;\">${ticks}</div>\r\n            <div class=\"gantt-rows\" style=\"width:${chartWidth}px; height:${withDates.length*rowHeight}px;\">${barsHtml}</div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    `;\r\n    const noDatesCount = total - withDates.length;\r\n    if(noDatesCount > 0){\r\n      html += `<p class=\"report-status-empty\" style=\"margin-top:14px;\">${noDatesCount} task(s) without both dates are not shown above.</p>`;\r\n    }\r\n  }\r\n\r\n  await saveReportSnapshot(html, 'timeline');\r\n  openGeneratedReport(html);\r\n});\r\n\r\ndocument.getElementById('reportBack').addEventListener('click', () => {\r\n  document.getElementById('reportView').classList.remove('open');\r\n  if(reportBackTarget === 'history') document.getElementById('historyView').classList.add('open');\r\n  reportBackTarget = 'checklist';\r\n});\r\ndocument.getElementById('reportPrint').addEventListener('click', () => window.print());\r\n\r\ndocument.getElementById('reportDownload').addEventListener('click', () => {\r\n  const contentHtml = document.getElementById('reportContent').innerHTML;\r\n  const titleEl = document.getElementById('reportContent').querySelector('h1');\r\n  const title = titleEl ? titleEl.textContent : (currentSpace ? currentSpace.name + ' — Report' : 'Report');\r\n  const standaloneCss = `\r\n    :root{ --ink:#211d18; --ink-soft:#6b6357; --line:#cfc6b2; --panel:#f6f3ea; --accent:#d9541c;\r\n      --amber:#e2a100; --green:#4c7a3d; --stone:#9a9080; }\r\n    *{ box-sizing:border-box; }\r\n    body{\r\n      font-family:'Archivo',Arial,sans-serif; font-size:15px; line-height:1.6; color:var(--ink);\r\n      background:#fff; margin:0; padding:30px 24px 60px; max-width:760px; margin-inline:auto;\r\n    }\r\n    .report-header{ border-bottom:3px solid var(--ink); padding-bottom:14px; margin-bottom:18px; }\r\n    .report-header h1{ font-size:22px; margin:0 0 4px; }\r\n    .report-header .meta{ font-size:12.5px; color:var(--ink-soft); }\r\n    .report-summary{ display:flex; gap:18px; margin:14px 0 22px; font-size:13px; flex-wrap:wrap; }\r\n    .report-cat{ font-size:14px; font-weight:800; margin:22px 0 10px; border-bottom:1px solid var(--line); padding-bottom:6px; }\r\n    .report-item{ margin-bottom:14px; padding-bottom:14px; border-bottom:1px solid #eee; }\r\n    .report-item .rt-title{ font-weight:700; font-size:14px; }\r\n    .report-badge{\r\n      display:inline-block; font-size:10.5px; font-weight:700; padding:2px 8px; border-radius:99px;\r\n      margin-inline-start:8px; color:#fff; vertical-align:middle;\r\n    }\r\n    .rb-notstarted{ background:var(--stone); } .rb-inprogress{ background:var(--amber); color:#231c04; } .rb-done{ background:var(--green); }\r\n    .report-item .rt-line{ font-size:12.5px; color:var(--ink-soft); margin-top:3px; }\r\n    .report-item img{ max-width:260px; max-height:200px; margin-top:8px; border-radius:4px; border:1px solid var(--line); display:block; }\r\n    .report-status-section{ margin:26px 0; }\r\n    .report-status-heading{\r\n      font-size:15px; font-weight:800; margin:0 0 12px; padding-bottom:6px; border-bottom:2px solid var(--line);\r\n      display:inline-block; padding-inline-end:10px;\r\n    }\r\n    .report-status-heading.sh-done{ color:var(--green); border-color:var(--green); }\r\n    .report-status-heading.sh-inprogress{ color:#8a6400; border-color:var(--amber); }\r\n    .report-status-heading.sh-notstarted{ color:var(--ink-soft); border-color:var(--stone); }\r\n    .report-status-empty{ font-size:13px; color:var(--ink-soft); font-style:italic; }\r\n    .report-status-item{ font-size:13.5px; line-height:1.7; margin:0 0 14px; }\r\n    .report-status-item .rt-cat{ font-size:11.5px; color:var(--ink-soft); }\r\n    .report-status-item img{ max-width:260px; max-height:200px; margin-top:6px; border-radius:4px; border:1px solid var(--line); display:block; }\r\n    .gantt-legend{ display:flex; gap:16px; font-size:12px; color:var(--ink-soft); margin:10px 0 18px; flex-wrap:wrap; }\r\n    .gantt-swatch{ display:inline-block; width:12px; height:12px; border-radius:2px; margin-inline-end:5px; vertical-align:middle; }\r\n    .gantt-swatch.gantt-done{ background:var(--green); }\r\n    .gantt-swatch.gantt-inprogress{ background:var(--amber); }\r\n    .gantt-swatch.gantt-notstarted{ background:var(--stone); }\r\n    .gantt-wrap{ display:flex; border:1px solid var(--line); border-radius:4px; overflow:hidden; }\r\n    .gantt-labels{ flex:0 0 auto; border-inline-end:1px solid var(--line); background:var(--panel); }\r\n    .gantt-label-header{ height:28px; line-height:28px; font-size:11px; font-weight:700; color:var(--ink-soft); padding:0 10px; border-bottom:1px solid var(--line); background:#efe9d8; box-sizing:border-box; }\r\n    .gantt-label-row{\r\n      height:34px; line-height:34px; padding:0 10px; font-size:12.5px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;\r\n      border-bottom:1px solid #eee; box-sizing:border-box;\r\n    }\r\n    .gantt-scroll{ overflow-x:auto; flex:1 1 auto; }\r\n    .gantt-ticks{ position:relative; height:28px; border-bottom:1px solid var(--line); background:#efe9d8; box-sizing:border-box; }\r\n    .gantt-tick{ position:absolute; top:0; height:28px; line-height:28px; font-size:10.5px; color:var(--ink-soft); padding-inline-start:4px; border-inline-start:1px solid var(--line); white-space:nowrap; box-sizing:border-box; }\r\n    .gantt-rows{ position:relative; background-image:repeating-linear-gradient(to bottom, transparent 0, transparent 33px, #eee 33px, #eee 34px); }\r\n    .gantt-bar{\r\n      position:absolute; height:22px; border-radius:4px; display:flex; align-items:center; overflow:hidden;\r\n      padding:0 6px; box-sizing:border-box;\r\n    }\r\n    .gantt-bar-label{ font-size:11px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; color:#fff; }\r\n    .gantt-bar.gantt-done{ background:var(--green); }\r\n    .gantt-bar.gantt-inprogress{ background:var(--amber); }\r\n    .gantt-bar.gantt-inprogress .gantt-bar-label{ color:#231c04; }\r\n    .gantt-bar.gantt-notstarted{ background:var(--stone); }\r\n  `;\r\n  const doc = `<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n<title>${escapeHtml(title)}</title>\r\n<style>${standaloneCss}</style>\r\n</head>\r\n<body>\r\n${contentHtml}\r\n</body>\r\n</html>`;\r\n  const blob = new Blob([doc], { type: 'text/html' });\r\n  const url = URL.createObjectURL(blob);\r\n  const a = document.createElement('a');\r\n  const safeName = (currentSpace ? currentSpace.name : 'report').replace(/[^a-z0-9\\-_]+/gi, '_');\r\n  a.href = url; a.download = `${safeName}-report-${todayStr()}.html`;\r\n  a.click();\r\n  URL.revokeObjectURL(url);\r\n  showToast('Report HTML downloaded');\r\n});\r\n\r\n/* ================= Report history ================= */\r\ndocument.getElementById('historyBtn').addEventListener('click', async () => {\r\n  const entries = await dbGetAllByIndex('reportHistory', 'spaceId', currentSpace.id);\r\n  entries.sort((a,b) => (b.reportDate||'').localeCompare(a.reportDate||'') || b.generatedAt - a.generatedAt);\r\n  const list = document.getElementById('historyList');\r\n  if(entries.length === 0){\r\n    list.innerHTML = `<h1 style=\"font-size:20px;margin:0 0 6px;\">${escapeHtml(currentSpace.name)} &mdash; Report History</h1>\r\n      <div class=\"empty\">No saved reports yet. Tap \"Generate report\" to create and save one.</div>`;\r\n  } else {\r\n    list.innerHTML = `<h1 style=\"font-size:20px;margin:0 0 14px;\">${escapeHtml(currentSpace.name)} &mdash; Report History</h1>` +\r\n      entries.map(en => `\r\n        <div class=\"history-item\">\r\n          <div>\r\n            <div class=\"history-date\">${formatDate(en.reportDate)} <span class=\"history-meta\">&middot; ${reportTypeLabel(en.type||'category')}</span></div>\r\n            <div class=\"history-meta\">Saved ${new Date(en.generatedAt).toLocaleString()}</div>\r\n          </div>\r\n          <button class=\"history-view-btn\" data-id=\"${en.id}\">View report</button>\r\n        </div>\r\n      `).join('');\r\n  }\r\n  document.getElementById('historyView').classList.add('open');\r\n  window.scrollTo(0,0);\r\n});\r\ndocument.getElementById('historyList').addEventListener('click', async e => {\r\n  const btn = e.target.closest('.history-view-btn');\r\n  if(!btn) return;\r\n  const entry = await dbGet('reportHistory', btn.dataset.id);\r\n  if(!entry) return;\r\n  const frame = document.createElement('iframe'); frame.setAttribute('sandbox',''); frame.title='Saved report'; frame.style.cssText='width:100%;height:75vh;border:0'; frame.srcdoc='<style>body{font:14px Arial;padding:20px}img{max-width:100%}</style>'+entry.html; document.getElementById('reportContent').replaceChildren(frame);\r\n  reportBackTarget = 'history';\r\n  document.getElementById('reportBack').textContent = '← Back to history';\r\n  document.getElementById('historyView').classList.remove('open');\r\n  document.getElementById('reportView').classList.add('open');\r\n  window.scrollTo(0,0);\r\n});\r\ndocument.getElementById('historyBack').addEventListener('click', () => document.getElementById('historyView').classList.remove('open'));\r\n\r\n/* ================= Backup / restore all data ================= */\r\ndocument.getElementById('backupBtn').addEventListener('click', async () => {\r\n  const spaces = await dbGetAll('spaces');\r\n  const allTasks = await dbGetAll('tasks');\r\n  const allPhotos = await dbGetAll('photos');\r\n  const allHistory = await dbGetAll('reportHistory');\r\n  const payload = { version:2, exportedAt: new Date().toISOString(), spaces, tasks: allTasks, photos: allPhotos, reportHistory: allHistory };\r\n  const blob = new Blob([JSON.stringify(payload)], { type:'application/json' });\r\n  const url = URL.createObjectURL(blob);\r\n  const a = document.createElement('a');\r\n  a.href = url; a.download = `site-tracker-backup-${new Date().toISOString().slice(0,10)}.json`;\r\n  a.click();\r\n  URL.revokeObjectURL(url);\r\n  showToast('Backup downloaded');\r\n});\r\n\r\n/* ================= Export all reports as a standalone browsable HTML file ================= */\r\ndocument.getElementById('exportReportsBtn').addEventListener('click', async () => {\r\n  const spaces = await dbGetAll('spaces');\r\n  const allHistory = await dbGetAll('reportHistory');\r\n  if(allHistory.length === 0){\r\n    alert('There are no saved reports yet. Open a space and generate a report (Generate report, Detailed status report, or Timeline) first.');\r\n    return;\r\n  }\r\n  const spaceNameById = Object.fromEntries(spaces.map(s => [s.id, s.name]));\r\n  const reports = allHistory\r\n    .map(h => ({\r\n      spaceName: spaceNameById[h.spaceId] || 'Unknown space',\r\n      reportDate: h.reportDate,\r\n      type: h.type || 'category',\r\n      generatedAt: h.generatedAt,\r\n      html: h.html\r\n    }))\r\n    .sort((a,b) => a.spaceName.localeCompare(b.spaceName) || (b.reportDate||'').localeCompare(a.reportDate||''));\r\n\r\n  // Pure static HTML/CSS navigation (:target), no JavaScript at all - a\r\n  // JS-driven version previously showed only the header and nothing else\r\n  // on mobile: large downloaded HTML files often open in a lightweight\r\n  // \"Quick Look\"-style preview (notably on iOS) that renders markup but\r\n  // never executes <script>, and even in a real mobile browser a single\r\n  // multi-megabyte inline script can fail to parse silently. Anchor links\r\n  // plus :target work in any renderer that understands HTML/CSS at all.\r\n  const groups = new Map();\r\n  reports.forEach((r, i) => { r._idx = i; if(!groups.has(r.spaceName)) groups.set(r.spaceName, []); groups.get(r.spaceName).push(r); });\r\n\r\n  let reportPages = '';\r\n  reports.forEach(r => {\r\n    reportPages += `<div id=\"report-${r._idx}\" class=\"report-page-wrap\">\r\n      <a href=\"#list\" class=\"back-link\">&larr; Back to reports</a>\r\n      <div class=\"report-page\">${r.html}</div>\r\n    </div>`;\r\n  });\r\n\r\n  let listHtml = '';\r\n  groups.forEach((items, spaceName) => {\r\n    listHtml += `<div class=\"space-group\"><h2>${escapeHtml(spaceName)}</h2>`;\r\n    items.forEach(r => {\r\n      const shortLabel = r.type === 'status' ? 'Detailed status' : r.type === 'timeline' ? 'Timeline' : 'Checklist';\r\n      listHtml += `<a class=\"report-row\" href=\"#report-${r._idx}\">\r\n        <span><span class=\"rr-date\">${formatDate(r.reportDate)}</span>\r\n        <span class=\"rr-meta\">Saved ${new Date(r.generatedAt).toLocaleString()}</span></span>\r\n        <span class=\"rr-type${r.type ? ' ' + r.type : ''}\">${shortLabel}</span>\r\n      </a>`;\r\n    });\r\n    listHtml += `</div>`;\r\n  });\r\n\r\n  const doc = `<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n<title>Site Finishing Tracker &mdash; Reports</title>\r\n<style>\r\n  :root{ --ink:#211d18; --ink-soft:#6b6357; --line:#cfc6b2; --panel:#f6f3ea; --bg:#eae6dc; --accent:#d9541c;\r\n    --amber:#e2a100; --green:#4c7a3d; --stone:#9a9080; }\r\n  *{ box-sizing:border-box; }\r\n  body{ font-family:'Archivo',Arial,sans-serif; font-size:15px; line-height:1.6; color:var(--ink); background:var(--bg); margin:0; }\r\n  header{ background:var(--ink); color:#f2ede0; padding:16px; border-bottom:4px solid var(--accent); }\r\n  header h1{ font-size:18px; margin:0; }\r\n  header .sub{ font-size:12px; color:#c9c0ac; margin:4px 0 0; }\r\n  .back-link{\r\n    display:inline-block; border:1px solid #4a453a; background:transparent; color:var(--ink); border-radius:3px;\r\n    padding:7px 10px; font-size:13px; text-decoration:none; margin-bottom:14px;\r\n  }\r\n  main{ max-width:760px; margin:0 auto; padding:16px; }\r\n  .space-group{ margin-bottom:26px; }\r\n  .space-group h2{ font-size:15px; border-bottom:2px solid var(--line); padding-bottom:6px; margin:0 0 10px; }\r\n  .report-row{\r\n    background:var(--panel); border:1px solid var(--line); border-inline-start:4px solid var(--accent); border-radius:3px;\r\n    padding:12px 14px; margin-bottom:8px; cursor:pointer; display:flex; justify-content:space-between; align-items:center; gap:10px;\r\n    text-decoration:none; color:inherit;\r\n  }\r\n  .report-row:hover{ border-color:var(--accent); }\r\n  .report-row .rr-date{ font-weight:700; font-size:14px; display:block; }\r\n  .report-row .rr-meta{ font-size:11.5px; color:var(--ink-soft); margin-top:2px; display:block; }\r\n  .report-row .rr-type{ font-size:10.5px; font-weight:700; padding:3px 9px; border-radius:99px; color:#fff; background:var(--stone); flex:0 0 auto; white-space:nowrap; }\r\n  .report-row .rr-type.status{ background:#5b7fb0; }\r\n  .report-row .rr-type.timeline{ background:#7a5bb0; }\r\n  .report-page-wrap{ display:none; background:#fff; margin:-16px -16px 0; padding:24px 16px 60px; }\r\n  .report-page-wrap:target{ display:block; }\r\n  .report-page-wrap:target ~ #list{ display:none; }\r\n  #list{ display:block; }\r\n  .report-header{ border-bottom:3px solid var(--ink); padding-bottom:14px; margin-bottom:18px; }\r\n  .report-header h1{ font-size:22px; margin:0 0 4px; }\r\n  .report-header .meta{ font-size:12.5px; color:var(--ink-soft); }\r\n  .report-summary{ display:flex; gap:18px; margin:14px 0 22px; font-size:13px; flex-wrap:wrap; }\r\n  .report-cat{ font-size:14px; font-weight:800; margin:22px 0 10px; border-bottom:1px solid var(--line); padding-bottom:6px; }\r\n  .report-item{ margin-bottom:14px; padding-bottom:14px; border-bottom:1px solid #eee; }\r\n  .report-item .rt-title{ font-weight:700; font-size:14px; }\r\n  .report-badge{ display:inline-block; font-size:10.5px; font-weight:700; padding:2px 8px; border-radius:99px; margin-inline-start:8px; color:#fff; vertical-align:middle; }\r\n  .rb-notstarted{ background:var(--stone); } .rb-inprogress{ background:var(--amber); color:#231c04; } .rb-done{ background:var(--green); }\r\n  .report-item .rt-line{ font-size:12.5px; color:var(--ink-soft); margin-top:3px; }\r\n  .report-item img{ max-width:260px; max-height:200px; margin-top:8px; border-radius:4px; border:1px solid var(--line); display:block; }\r\n  .report-status-section{ margin:26px 0; }\r\n  .report-status-heading{ font-size:15px; font-weight:800; margin:0 0 12px; padding-bottom:6px; border-bottom:2px solid var(--line); display:inline-block; padding-inline-end:10px; }\r\n  .report-status-heading.sh-done{ color:var(--green); border-color:var(--green); }\r\n  .report-status-heading.sh-inprogress{ color:#8a6400; border-color:var(--amber); }\r\n  .report-status-heading.sh-notstarted{ color:var(--ink-soft); border-color:var(--stone); }\r\n  .report-status-empty{ font-size:13px; color:var(--ink-soft); font-style:italic; }\r\n  .report-status-item{ font-size:13.5px; line-height:1.7; margin:0 0 14px; }\r\n  .report-status-item .rt-cat{ font-size:11.5px; color:var(--ink-soft); }\r\n  .report-status-item img{ max-width:260px; max-height:200px; margin-top:6px; border-radius:4px; border:1px solid var(--line); display:block; }\r\n  .gantt-legend{ display:flex; gap:16px; font-size:12px; color:var(--ink-soft); margin:10px 0 18px; flex-wrap:wrap; }\r\n  .gantt-swatch{ display:inline-block; width:12px; height:12px; border-radius:2px; margin-inline-end:5px; vertical-align:middle; }\r\n  .gantt-swatch.gantt-done{ background:var(--green); }\r\n  .gantt-swatch.gantt-inprogress{ background:var(--amber); }\r\n  .gantt-swatch.gantt-notstarted{ background:var(--stone); }\r\n  .gantt-wrap{ display:flex; border:1px solid var(--line); border-radius:4px; overflow:hidden; }\r\n  .gantt-labels{ flex:0 0 auto; border-inline-end:1px solid var(--line); background:var(--panel); }\r\n  .gantt-label-header{ height:28px; line-height:28px; font-size:11px; font-weight:700; color:var(--ink-soft); padding:0 10px; border-bottom:1px solid var(--line); background:#efe9d8; box-sizing:border-box; }\r\n  .gantt-label-row{\r\n    height:34px; line-height:34px; padding:0 10px; font-size:12.5px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;\r\n    border-bottom:1px solid #eee; box-sizing:border-box;\r\n  }\r\n  .gantt-scroll{ overflow-x:auto; flex:1 1 auto; }\r\n  .gantt-ticks{ position:relative; height:28px; border-bottom:1px solid var(--line); background:#efe9d8; box-sizing:border-box; }\r\n  .gantt-tick{ position:absolute; top:0; height:28px; line-height:28px; font-size:10.5px; color:var(--ink-soft); padding-inline-start:4px; border-inline-start:1px solid var(--line); white-space:nowrap; box-sizing:border-box; }\r\n  .gantt-rows{ position:relative; background-image:repeating-linear-gradient(to bottom, transparent 0, transparent 33px, #eee 33px, #eee 34px); }\r\n  .gantt-bar{\r\n    position:absolute; height:22px; border-radius:4px; display:flex; align-items:center; overflow:hidden;\r\n    padding:0 6px; box-sizing:border-box;\r\n  }\r\n  .gantt-bar-label{ font-size:11px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; color:#fff; }\r\n  .gantt-bar.gantt-done{ background:var(--green); }\r\n  .gantt-bar.gantt-inprogress{ background:var(--amber); }\r\n  .gantt-bar.gantt-inprogress .gantt-bar-label{ color:#231c04; }\r\n  .gantt-bar.gantt-notstarted{ background:var(--stone); }\r\n</style>\r\n</head>\r\n<body>\r\n<header>\r\n  <h1>Site Finishing Tracker &mdash; Reports</h1>\r\n  <p class=\"sub\">${reports.length} saved report(s)</p>\r\n</header>\r\n<main>\r\n${reportPages}\r\n  <div id=\"list\">\r\n${listHtml}\r\n  </div>\r\n</main>\r\n</body>\r\n</html>`;\r\n  const blob = new Blob([doc], { type: 'text/html' });\r\n  const url = URL.createObjectURL(blob);\r\n  const a = document.createElement('a');\r\n  a.href = url; a.download = `site-tracker-reports-${todayStr()}.html`;\r\n  a.click();\r\n  URL.revokeObjectURL(url);\r\n  showToast(`${reports.length} report(s) exported`);\r\n});\r\n\r\ndocument.getElementById('restoreBtn').addEventListener('click', () => document.getElementById('restoreInput').click());\r\ndocument.getElementById('restoreInput').addEventListener('change', e => {\r\n  const file = e.target.files[0];\r\n  if(!file) return;\r\n  const reader = new FileReader();\r\n  reader.onload = async evt => {\r\n    let payload;\r\n    try{\r\n      payload = JSON.parse(evt.target.result);\r\n    }catch(err){\r\n      alert('This file could not be read as a valid backup (not valid JSON).');\r\n      return;\r\n    }\r\n    if(!payload || !Array.isArray(payload.spaces) || !Array.isArray(payload.tasks)){\r\n      alert('This file does not look like a Site Finishing Tracker backup.');\r\n      return;\r\n    }\r\n    if(!confirm(`This will add ${payload.spaces.length} space(s) from the backup. Continue?`)) return;\r\n    try{\r\n      for(const s of payload.spaces) await dbPut('spaces', s);\r\n      for(const t of payload.tasks) await dbPut('tasks', t);\r\n      for(const p of (payload.photos||[])) await dbPut('photos', p);\r\n      for(const h of (payload.reportHistory||[])) await dbPut('reportHistory', h);\r\n      showToast('Backup restored');\r\n      renderHome();\r\n    }catch(err){ alert('Restore failed while saving data: ' + err.message); }\r\n  };\r\n  reader.onerror = () => alert('This file could not be read.');\r\n  reader.readAsText(file);\r\n});\r\n\r\n/* ================= Edit / delete spaces ================= */\r\ndocument.getElementById('editSpacesBtn').addEventListener('click', () => {\r\n  editMode = !editMode;\r\n  selectedSpaceIds = new Set();\r\n  updateEditUI();\r\n  renderHome();\r\n});\r\ndocument.getElementById('selectAllBtn').addEventListener('click', async () => {\r\n  const spaces = await dbGetAll('spaces');\r\n  if(selectedSpaceIds.size === spaces.length){\r\n    selectedSpaceIds = new Set();\r\n  } else {\r\n    selectedSpaceIds = new Set(spaces.map(s => s.id));\r\n  }\r\n  updateEditUI();\r\n  renderHome();\r\n});\r\ndocument.getElementById('deleteSelectedBtn').addEventListener('click', async () => {\r\n  const n = selectedSpaceIds.size;\r\n  if(n === 0) return;\r\n  if(!confirm(`Delete ${n} space${n > 1 ? 's' : ''}? This removes all of its tasks, photos, and report history. This cannot be undone.`)) return;\r\n  for(const id of selectedSpaceIds) await deleteSpace(id);\r\n  showToast(`${n} space${n > 1 ? 's' : ''} deleted`);\r\n  editMode = false;\r\n  selectedSpaceIds = new Set();\r\n  updateEditUI();\r\n  renderHome();\r\n});\r\n\r\n/* ================= Init ================= */\r\nopenDB().then(async () => { const id = new URLSearchParams(location.search).get('space'); if(id) await openSpace(id); else showHome(); }).catch(() => {\r\n  document.getElementById('main').innerHTML = '<div class=\"empty\">Online storage is unavailable. Please reload and try again.</div>';\r\n});\r\n</script>\r\n<style>[hidden]{display:none!important}body:not([data-role=\"administrator\"]) button[onclick^=\"newProject\"],body:not([data-role=\"administrator\"]) [data-edit-project],body:not([data-role=\"administrator\"]) [data-edit-visit],body:not([data-role=\"administrator\"]) #addBtn,body:not([data-role=\"administrator\"]) #editSpacesBtn,body:not([data-role=\"administrator\"]) #selectAllBtn,body:not([data-role=\"administrator\"]) #deleteSelectedBtn,body:not([data-role=\"administrator\"]) #importExcelBtn,body:not([data-role=\"administrator\"]) #renameSpaceBtn,body:not([data-role=\"administrator\"]) #reportDateBtn,body:not([data-role=\"administrator\"]) #restoreBtn,body:not([data-role=\"administrator\"]) .drag-handle{display:none!important}body[data-role=\"management\"] button[onclick^=\"newVisit\"],body[data-role=\"management\"] #reportBtn,body[data-role=\"management\"] #statusReportBtn,body[data-role=\"management\"] #timelineBtn{display:none!important}\n</style><script>// Display-only permissions. Every API operation is independently authorized on the server.\r\nfetch('/api/5s/session').then(async response=>{\r\n if(!response.ok)return;const {user}=await response.json();\r\n const readOnly=user.role!=='administrator';\r\n document.body.dataset.role=user.role;\r\n const update=()=>{\r\n  document.querySelectorAll('button[onclick^=\"newProject\"],button[data-edit-project],button[data-edit-visit]').forEach(button=>button.hidden=user.role!=='administrator');\r\n  document.querySelectorAll('button[onclick^=\"newVisit\"]').forEach(button=>button.hidden=user.role==='management');\r\n  if(!readOnly)return;\r\n  document.querySelectorAll('button[data-edit-visit],#addBtn,#editSpacesBtn,#selectAllBtn,#deleteSelectedBtn,#importExcelBtn,#renameSpaceBtn,#reportDateBtn,#restoreBtn').forEach(button=>{button.disabled=true;button.style.setProperty('display','none','important')});\r\n  document.querySelectorAll('#main input,#main textarea,#main button').forEach(control=>control.disabled=true);\r\n  document.querySelectorAll('.drag-handle').forEach(control=>control.style.display='none');\r\n  document.querySelectorAll('.status-btn,.drag-handle').forEach(control=>control.style.pointerEvents='none');\r\n };\r\n update();const main=document.getElementById('app')||document.getElementById('main');if(main)new MutationObserver(update).observe(main,{subtree:true,childList:true});\r\n}).catch(()=>{});\r\n</script></body>\r\n</html>\r\n\r\n";
